head.script:
/***************************************************************************************
* 시스템명 : 문서접수관리
* 업무명   : 업무공통
* 파일명   : as-is : QA0102.xml
* 파일명   : to-be : CM0101101M.xml
* 작성자   : YANG
* 작성일   : 2024.12.12
*
* 설 명 : 보상문서관리
*---------------------------------------------------------------------------------------
* 변경일 변경자 변경내역
*---------------------------------------------------------------------------------------
* 2024.12.12 YANG	최초 프로그램 작성
*
*---------------------------------------------------------------------------------------
****************************************************************************************/
scwin.v_Gyeoljae      = true; //공통결재영역 존재여부
scwin.v_SujeongModeYN = ""; //수정모드 on/off
scwin.v_EmailcolNms   = ["MIGAIP_SAEOPJANG_EMAIL", "JAEHAEJA_EMAIL", "MINWONIN_EMAIL"];
scwin.v_MinGwangyeCd  = "" ;
scwin.v_FocusFg		  = "Y";

// parent 변수
scwin.v_PFormloadFg     = $p.parent().scwin.v_PFormloadFg;
scwin.v_PMinwonDocCd    = $p.parent().scwin.v_PMinwonDocCd;
scwin.v_PMinwonDocNm    = $p.parent().scwin.v_PMinwonDocNm;
scwin.v_PJeopstNo       = $p.parent().scwin.v_PJeopstNo;
scwin.v_PMinwonDocChkFg = $p.parent().scwin.v_PMinwonDocChkFg;

/*******************************************************************************
 * FUNCTION 명 : onpageload
 * FUNCTION 기능설명 : 화면 페이지 로드
*******************************************************************************/
scwin.onpageload = async function() {    
   	await com.gfn_LoadForm();
	scwin.fn_Init();
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_Init
 * FUNCTION 기능설명 : 화면 초기화.
*******************************************************************************/
scwin.fn_Init = function()
{	debugger;
	$p.parent().gyeoljaeBar.show();
	// 이벤트 바인드 처리
	scwin.fn_Dma_JeopsuInfoBindYn(false);

	scwin.fn_InitAllDataSet();
	scwin.fn_InitComboBoxForCommonCode();

	dma_JeopsuInfo.set("MINWONIN_GWANGYE_CD", "01");
	dma_JeopsuInfo.set("JEOPSU_ILSI", com.substr(com.gfn_GetDate(), 0, 12));

	dma_JeopsuInfo.set("JEOPSUJA_ID", com.gfn_SsGetId());
	dma_JeopsuInfo.set("JEOPSUJA_NM", com.gfn_SsGetName());
    dma_JeopsuInfo.set("MINWON_FG"  , "2");

	edt_JaehaejaInfo_jaehaejaEmailCombo.setValue("9999");
	edt_JaehaejaInfo_migaipSaeopjangEmailCombo.setValue("9999");
	edt_MinwoninInfo_minwoninEmailCombo.setValue("9999");

	scwin.v_SujeongModeYN = "N"; //open시 수정모드 OFF

	cob_DamdangjaInfo_damdangjaChangeSayuCd.setValue("");
	cob_DaeriinInfo_daeriinFg.setValue("");	
	chk_Foreigner_Mibalgeup_Yn.setValue("N"); 

	btn_GibdanMinwonHwamyeonYg.setDisabled(true);
	edt_JeopsuInfo_jeopsuIlsi.setDisabled(false);
	btn_JaehaejaInfo_SelectMigaipSaeopjangPostPup.setDisabled(true);
	st_Isong_Yn.setValue(""); 

	com.gfn_disableRButton("0");

	btn_Jeopsujeung.setDisabled(true); 
	btn_GitaCheori.setDisabled(true); 
	btn_Save.setDisabled(false); 

	// dma_JeopsuInfo.ApplyChange();
	edt_JeopsuInfo_minwonDocCd.focus();

	// 이벤트 바인드 처리
	scwin.fn_Dma_JeopsuInfoBindYn(true);
	dma_JeopsuInfo.initRowStatus();

	if (!com.gfn_IsNull(scwin.v_PFormloadFg)) {
		if (scwin.v_PFormloadFg == "J") {
			scwin.fn_RetrieveMinwonJeopsuInfo(scwin.v_PJeopstNo);	
			scwin.v_PFormloadFg = "S";
		} 
	}
	dma_JeopsuInfo.reform();
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_InitAllDataSet
 * FUNCTION 기능설명 : 모든 DataSet을 초기화
*******************************************************************************/
scwin.fn_InitAllDataSet = function()
{
	// 민원접수조회조건 DataSet
	dma_MinwonJeopsuJohoeJogeon.setEmptyValue();
	dma_MinwonJeopsuJohoeJogeon.reform();

	// 접수정보 DataSet
	dma_JeopsuInfo.setEmptyValue();
	dma_JeopsuInfo.reform();

	// 재해근로자정보 DataSet
	dma_JaehaejaInfo.setEmptyValue();
	dma_JaehaejaInfo.reform();

	// 담당자정보 DataSet
	dma_DamdangjaInfo.setEmptyValue();
	dma_DamdangjaInfo.reform();

    // 서비스대상 DataSet
	dma_ServiceDaesangInfo.setEmptyValue();
	dma_ServiceDaesangInfo.reform();

    // 원부번호 DataSet
	dma_WonbuNoInfo.setEmptyValue();
	dma_WonbuNoInfo.reform();
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_InitComboBoxForCommonCode
 * FUNCTION 기능설명 : 공통코드 조회
*******************************************************************************/
scwin.fn_InitComboBoxForCommonCode = function()
{
	var codeOptions = [
		{ code : "A0060", compID : "cob_JeopsuInfo_jeopsuBangsikCd", dataNm : "dlt_JeopsuBangsikCd" },
        { code : "B0092", compID : "cob_MinwoninInfo_minwoninGwangyeCd", dataNm : "dlt_MinwoninGwangyeCd" },
        { code : "Q0002", compID : "cob_DamdangjaInfo_damdangjaChangeSayuCd", dataNm : "dlt_DamdangjaChangeSayuCd" },
        { code : "Q0008", compID : "cob_DaeriinInfo_daeriinFg", dataNm : "dlt_DaeriinFg" },
        { code : "B0275", compID : "", dataNm : "dlt_ServiceDaesnagFg" },
	];

	com.setCommonCode( codeOptions, function(){		
        com.dataListFilter("dlt_JeopsuBangsikCd", "GT_CD != 'W'");
		cob_JeopsuInfo_jeopsuBangsikCd.setSelectedIndex(3); 
		cob_DaeriinYn.setSelectedIndex(0);
		dlt_JeopsuBangsikCd.reform();
		dma_JeopsuInfo.reform();
	});
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_RetrieveMinwonJeopsuInfo
 * FUNCTION 기능설명 : 민원접수조회조건에 따른 접수정보를 조회한다. 
*******************************************************************************/
scwin.fn_RetrieveMinwonJeopsuInfo = function(v_JeopsuNo) {    

	dma_MinwonJeopsuJohoeJogeon.set("JEOPSU_NO", v_JeopsuNo);

    /*
	var srvId		 = "RetrieveBosangMinwonJeopsuCmd";
	var strURL		 = "kcw.q.qa.cmd.RetrieveBosangMinwonJeopsuCmd.do";
	var strinDsList	 = "dma_MinwonJeopsuJohoeJogeon=dma_MinwonJeopsuJohoeJogeon";
	var stroutDsList = "dma_JeopsuInfo=dma_JeopsuInfo";
	var strArgument	 = "";
	var strCallback  = "scwin.fn_CallBack";
	*/
    $p.parent().dma_MinwonJeopsuJohoeJogeon.set("JEOPSU_NO", v_JeopsuNo);

	// RetrieveBosangMinwonJeopsuCmd
	com.executeSubmission(sbm_CM0101100M_E002);
}	

/*******************************************************************************
 * FUNCTION 명 : scwin.btn_JeopsuInfo_SelectMinwonDocCdPup_onclick
 * FUNCTION 기능설명 : 민원서류코드선택
*******************************************************************************/
scwin.btn_JeopsuInfo_SelectMinwonDocCdPup_onclick = async function(e)
{
	await $p.parent().scwin.fn_SubMinwonDocCdSet( edt_JeopsuInfo_minwonDocCd
	       					                    , dma_JeopsuInfo
						                        , "click"
						                        , edt_JeopsuInfo_jeopsuIlsi);

	var varOldValue= scwin.v_PMinwonDocCd;
	var varNewValue= dma_JeopsuInfo.get("MINWON_DOC_CD");
	var varOldValueNm = scwin.v_PMinwonDocNm;

	//접수구분이 전화상담접수(9)일 경우 
	if (scwin.v_SujeongModeYN == "Y" && dma_JeopsuInfo.get("JEOPSU_FG") == "9") {
		await com.gfn_MsgAlert("MQAA007");
		return false;
	}

	// 조회조건의 민원구분변경시 메세지처리
	var rev = await $p.parent().scwin.fn_SubUpdateCheckMinwonDocCd(varNewValue);
	if (!rev) {
		dma_JeopsuInfo.set("MINWON_DOC_CD", varOldValue);
		dma_JeopsuInfo.set("MINWON_DOC_NM", varOldValueNm);
		return;
	}

    scwin.fnc_MinwonSeosikExCheori(edt_JeopsuInfo_minwonDocCd.getValue()); 						

	var v_GihanArr ; 
	if (com.gfn_IsNull(dma_JeopsuInfo.get("JEOPSU_NO"))) {
        if (com.gfn_IsNull(dma_JeopsuInfo.get("MINWON_DOC_CD")) || com.length(dma_JeopsuInfo.get("MINWON_DOC_CD")) != 4 ){
            dma_JeopsuInfo.set("CHEORI_GIHAN", ""); 
        } else {
	        v_GihanArr = await scwin.fn_RetrieveMinwonCheoriGihan(); 

	        if (!com.gfn_IsNull(v_GihanArr[0])){
	            dma_JeopsuInfo.set("CHEORI_GIHAN", v_GihanArr[0]); 
	        } 
	    }
	}        							
}

/*******************************************************************************
 * FUNCTION 명 : scwin.edt_JeopsuInfo_minwonDocCd_onkeydown
 * FUNCTION 기능설명 : 민원서류코드선택
*******************************************************************************/
scwin.edt_JeopsuInfo_minwonDocCd_onkeydown = async function(e)
{ 
    if (e.keyCode == 13) {
		var varOldValue   = scwin.v_PMinwonDocCd;
		var varOldValueNm = scwin.v_PMinwonDocNm;

        edt_JeopsuInfo_minwonDocCd.commit();
		var varNewValue= dma_JeopsuInfo.get("MINWON_DOC_CD");

		//접수구분이 전화상담접수(9)일 경우 
		if (scwin.v_SujeongModeYN == "Y" && dma_JeopsuInfo.get("JEOPSU_FG") == "9") {
			await com.gfn_MsgAlert("MQAA007");
			return false;
		}

		// 조회조건의 민원구분변경시 메세지처리
		var rev = await $p.parent().scwin.fn_SubUpdateCheckMinwonDocCd(varNewValue);
		if (!rev) {
			dma_JeopsuInfo.set("MINWON_DOC_CD", varOldValue);
			dma_JeopsuInfo.set("MINWON_DOC_NM", varOldValueNm);
			return false;
		}

		if (com.gfn_IsNull(dma_JeopsuInfo.get("JEOPSU_NO"))) {
            if (!com.gfn_IsNull(dma_JeopsuInfo.get("MINWON_DOC_CD")) && com.length(com.trim(dma_JeopsuInfo.get("MINWON_DOC_CD"))) == 4 ) {
                v_GihanArr = await scwin.fn_RetrieveMinwonCheoriGihan(); 

	            if (!com.gfn_IsNull(v_GihanArr[0])) {
	                dma_JeopsuInfo.set("CHEORI_GIHAN", v_GihanArr[0]); 
	            }
            } else {
	            dma_JeopsuInfo.set("CHEORI_GIHAN", ""); 
	        }
	    }        

        await $p.parent().scwin.fn_SubMinwonDocCdSet( edt_JeopsuInfo_minwonDocCd
                                                    , dma_JeopsuInfo
                                                    , "keyDown"
                                                    , edt_JeopsuInfo_jeopsuIlsi);

        scwin.fnc_MinwonSeosikExCheori(edt_JeopsuInfo_minwonDocCd.getValue()); 
    }
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_RtnNextObj
 * FUNCTION 기능설명 : 민원서류코드에 따른 object 선택
*******************************************************************************/
scwin.fn_RtnNextObj = function() {
	var v_MinwonDocCd = dma_JeopsuInfo.get("MINWON_DOC_CD");

	var v_RtnObj;
	if ((v_MinwonDocCd == "1524" || v_MinwonDocCd == "1525" || 
		 v_MinwonDocCd == "1526" || v_MinwonDocCd == "1523" || v_MinwonDocCd == "1534") &&
		 dma_JeopsuInfo.get("MINWONIN_GWANGYE_CD") == "01") {

		v_RtnObj = cob_MinwoninInfo_minwoninGwangyeCd;
	} else {
		v_RtnObj = cob_JeopsuInfo_jeopsuBangsikCd;		
	}

	return v_RtnObj;
}

/*******************************************************************************
 * FUNCTION 명 : scwin.btn_JaehaejaInfo_SelectJaehaejaPup_onclick
 * FUNCTION 기능설명 : 재해자 조회
*******************************************************************************/ 
scwin.btn_JaehaejaInfo_SelectJaehaejaPup_onclick = function(e)
{
	scwin.fn_JaehaejaInfoJohoe("click");
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_JaehaejaInfoJohoe
 * FUNCTION 기능설명 : 재해자 조회
******************************************************************************/ 
scwin.fn_JaehaejaInfoJohoe = async function(action)
{   
	var v_Flag = action;
	var v_Param = "";

	if (com.substr(dma_JeopsuInfo.get("MINWON_DOC_CD"), 0, 2) == "36" && dma_JeopsuInfo.get("MINWON_DOC_CD") != "3614")
	{
	    v_Param = "v_JaehaejaRgno=" + com.trim(mae_JaehaejaInfo_jaehaejaRgno.getValue()) + " v_JeongmilFg=";
	}else{
	    // 민원서류코드식별을 위한 추가 (2016.06.16)
	    v_Param = "v_JaehaejaRgno=" + com.trim(mae_JaehaejaInfo_jaehaejaRgno.getValue()) + " v_MinwonDocCd=" + dma_JeopsuInfo.get("MINWON_DOC_CD"); 
	}

	var v_JaehaejaInfo = Array();

	v_JaehaejaInfo = await com.cfn_GetJaehaejaInfo(v_Flag, v_Param);

	if (!com.gfn_IsNull(v_JaehaejaInfo[0])) 
	{
		// dma_JeopsuInfo.FireEvent = false;
		dma_JeopsuInfo.unbind("onbeforemodelchange");
		dma_JeopsuInfo.unbind("onmodelchange");
		dma_JeopsuInfo.unbind("onsetdata");

        // 2012-05-21 문형수(D) 요청으로 변경(심사청구서(3300, 재해자정보가 2건이상일 경우 재해일자 수정안되도록 disable))
        if ( dma_JeopsuInfo.get("MINWON_DOC_CD") == "3300" && com.toNumber(v_JaehaejaInfo[30]) > 1 ) {     
            cal_JaehaejaInfo_jaehaeDt.setDisabled(true);  
        }

		if (dma_JeopsuInfo.get("MINWON_DOC_CD") != "1001")
		{	
			var v_MinwonDocCdJ = dma_JeopsuInfo.get("MINWON_DOC_CD");
			// 진단알자 세팅 : 진폐정밀진단이송료(3611), 진폐정밀진단휴업급여(3612)
			// 진단일자에 재해일자 세팅시 메세지 처리			
			if( v_MinwonDocCdJ == "3600" || v_MinwonDocCdJ == "3601" || v_MinwonDocCdJ == "3602" || 
				v_MinwonDocCdJ == "3603" || v_MinwonDocCdJ == "3623" || v_MinwonDocCdJ == "3611" ||
				v_MinwonDocCdJ == "3612" || v_MinwonDocCdJ == "3627" )
			{							
				if (com.gfn_IsNull(v_JaehaejaInfo[17])) 
				{
					if (!com.gfn_IsNull(v_JaehaejaInfo[2])) 
					{
						await com.gfn_Alert("정밀진단정보의 진단일자를 선택하여 처리하세요.");
						mae_JaehaejaInfo_jaehaejaRgno.focus();
						return;
					} 			
				}
				else
				{
					dma_JeopsuInfo.set("JAEHAE_DT", v_JaehaejaInfo[17]); 
				}
			}
			else if ( v_MinwonDocCdJ == "3614"   || v_MinwonDocCdJ == "3617" ) 
			{
				if (!com.gfn_IsNull(v_JaehaejaInfo[17])) 
				{
					dma_JeopsuInfo.set("JAEHAE_DT", v_JaehaejaInfo[17]);
				} 
				else 
				{
					dma_JeopsuInfo.set("JAEHAE_DT", v_JaehaejaInfo[2]);
				}
			}	
			else
			{
				dma_JeopsuInfo.set("JAEHAE_DT", v_JaehaejaInfo[2]);
			}
		}

		dma_JeopsuInfo.set("JAEHAEJA_RGNO"			, v_JaehaejaInfo[ 0]);
		dma_JeopsuInfo.set("JAEHAEJA_NM"		 	, v_JaehaejaInfo[ 1]);		
		dma_JeopsuInfo.set("WONBU_NO"			 	, v_JaehaejaInfo[ 3]);
		dma_JeopsuInfo.set("SE_WONBU_NO"		 	, v_JaehaejaInfo[ 4]);
		dma_JeopsuInfo.set("SAEOPJANG_NM"		 	, v_JaehaejaInfo[ 5]);
		dma_JeopsuInfo.set("HOSPITAL_NO"		 	, v_JaehaejaInfo[ 6]);
		dma_JeopsuInfo.set("HOSPITAL_NM"		 	, v_JaehaejaInfo[ 7]);
		dma_JeopsuInfo.set("JAEHAEJA_GIBON_ADDR" 	, v_JaehaejaInfo[18]);
		dma_JeopsuInfo.set("JAEHAEJA_SANGSE_ADDR"	, v_JaehaejaInfo[19]);
		dma_JeopsuInfo.set("JAEHAEJA_POST"			, v_JaehaejaInfo[12]);

		if (com.gfn_IsNull(v_JaehaejaInfo[20])) {
		    dma_JeopsuInfo.set("SAEOPGAESI_NO"          , "");
		    dma_JeopsuInfo.set("GS_WONBU_NO"            , "");
        } else {
            dma_JeopsuInfo.set("SAEOPGAESI_NO"          , scwin.fn_SeWonbuNoToGwanriNo(v_JaehaejaInfo[20]));
		    dma_JeopsuInfo.set("GS_WONBU_NO"            , v_JaehaejaInfo[20]);
        }

		dma_JeopsuInfo.set("JAEHAEJA_DDD"			, v_JaehaejaInfo[23]);
		dma_JeopsuInfo.set("JAEHAEJA_TEL1"			, v_JaehaejaInfo[24]);
		dma_JeopsuInfo.set("JAEHAEJA_TEL2"			, v_JaehaejaInfo[25]);
		dma_JeopsuInfo.set("JAEHAEJA_HP_DDD"		, v_JaehaejaInfo[26]);
		dma_JeopsuInfo.set("JAEHAEJA_HP_TEL1"		, v_JaehaejaInfo[27]);
		dma_JeopsuInfo.set("JAEHAEJA_HP_TEL2"		, v_JaehaejaInfo[28]);
		dma_JeopsuInfo.set("JAEHAEJA_EMAIL"			, v_JaehaejaInfo[29]);
		dma_JeopsuInfo.set("NEW_ADDR_YN"			, v_JaehaejaInfo[31]); //새주소여부 SET (2016.10.05)
		$p.parent().scwin.fn_SubEmailSet(dma_JeopsuInfo, scwin.v_EmailcolNms, "Split");

		//민원인정보 => 민원인관계가 01 : 본인 이면 
		if(dma_JeopsuInfo.get("MINWONIN_GWANGYE_CD") == "01") 
		{
		    scwin.fn_MinwoninSet(true); 	//재해근로자정보를 민원인정보에 셋
		}

		dma_JeopsuInfo.set("GWANRI_NO", v_JaehaejaInfo[13]);

		// dma_JeopsuInfo.FireEvent = true;
		dma_JeopsuInfo.bind("onbeforemodelchange", scwin.dma_JeopsuInfo_onbeforemodelchange);
		dma_JeopsuInfo.bind("onmodelchange"      , scwin.dma_JeopsuInfo_onmodelchange);
		dma_JeopsuInfo.bind("onsetdata"          , scwin.dma_JeopsuInfo_onsetdata);

		if (!com.gfn_IsNull(dma_JeopsuInfo.get("WONBU_NO"))) {

			var v_ServiceDaesangInfo = await qa.cfn_GetServiceDaesangInfo(dma_JeopsuInfo.get("WONBU_NO"));			
			dma_ServiceDaesangInfo.setEmptyValue();
			dma_ServiceDaesangInfo.set("SERVICE_DAESANG_FG", v_ServiceDaesangInfo[0]);
		} else {
			dma_ServiceDaesangInfo.setEmptyValue();
		}
		edt_JaehaejaInfo_telNo.focus();

		edt_GMJDCd.setValue("");

		var v_GMJD = "";
		var v_GMJD = await az.cfn_GetGwagyeokMinwonJeongdo(com.trim(mae_JaehaejaInfo_jaehaejaRgno.getValue()),"");

		edt_GMJDCd.setValue(v_GMJD);
	} 
}

/*******************************************************************************
 * FUNCTION 명 : scwin.btn_JaehaejaInfo_SelectJaehaejaPostPup_onclick
 * FUNCTION 기능설명 : 우편번호 조회팝업
*******************************************************************************/ 	
scwin.btn_JaehaejaInfo_SelectJaehaejaPostPup_onclick = function(e)
{	
	scwin.fn_PostSet(btn_JaehaejaInfo_SelectJaehaejaPostPup, "click", "JAEHAEJA", edt_JaehaejaInfo_addr3, dma_JeopsuInfo);
}

/*******************************************************************************
 * FUNCTION 명 : scwin.mae_JaehaejaInfo_addr_onkeydown
 * FUNCTION 기능설명 : 재해자 주소 keydown
*******************************************************************************/ 	
scwin.mae_JaehaejaInfo_addr_onkeydown = function(e)
{
	if (e.keyCode == "13") {
		// keyDown이벤트가 change이벤트보다 먼저발생하기때문에 강제 설정해준다.
		mae_JaehaejaInfo_addr.commit()
		scwin.fn_PostSet(mae_JaehaejaInfo_addr, "keyDown", "JAEHAEJA", edt_JaehaejaInfo_addr3, dma_JeopsuInfo);
	}
}

/*******************************************************************************
 * FUNCTION 명 : scwin.btn_JaehaejaInfo_SelectMigaipSaeopjangPostPup_onclick
 * FUNCTION 기능설명 : 미가입사업장우편번호선택 
*******************************************************************************/ 
scwin.btn_JaehaejaInfo_SelectMigaipSaeopjangPostPup_onclick = function(e)
{
	scwin.fn_PostSet(btn_JaehaejaInfo_SelectMigaipSaeopjangPostPup, "click", "MIGAIP_SAEOPJANG", edt_JaehaejaInfo_migaipSaeopjangAddr3, dma_JeopsuInfo);
