/**
 * 우편번호를 조회할 수 있는 화면을 Open하고 선택된 우편번호, 우편번호일련번호, 기본주소를 가져와 대리인정보.우편번호, 대리인정보.우편번호일련번호, 대리인정보.기본주소에 출력한다.
 * param : obj
 * return: 없음 
 */
/*******************************************************************************
 * FUNCTION 명 : scwin.fn_PostSet
 * FUNCTION 기능설명 : 우편번호 조회
*******************************************************************************/ 
scwin.fn_PostSet = async function(obj, v_Flag, v_StrKey, nextObj, dsObj) {

	var v_Post	= com.trim(dsObj.get(v_StrKey + "_POST"));	// 우편번호
	var v_Param = "v_Post=" + v_Post;
	var v_SelectSaeopjangPost = await com.gfn_GetPostAddrInfo(v_Flag, v_Param);

	if(!com.gfn_IsNull(v_SelectSaeopjangPost[0])){
		dsObj.set(v_StrKey + "_POST"		, v_SelectSaeopjangPost[0]);
		dsObj.set(v_StrKey + "_POST_SER"	, v_SelectSaeopjangPost[3]);
		dsObj.set(v_StrKey + "_GIBON_ADDR"	, v_SelectSaeopjangPost[1]);

		if(v_SelectSaeopjangPost[7] == "1") {
			dsObj.set(v_StrKey + "_SANGSE_ADDR", v_SelectSaeopjangPost[6]);
			//우편번호 팝업에서 도로명을 선택하고 입력했을경우 새주소여부에 Y값 SET (2016.10.05)
			dsObj.set("NEW_ADDR_YN" , "Y");
		}else{
			//우편번호 팝업에서 읍면을 선택하고 입력했을경우 새주소여부에 N값 SET (2016.10.05)
			dsObj.set("NEW_ADDR_YN" , "N");		
		}
		nextObj.focus();
	} else {
		obj.focus();
	}
}

/*******************************************************************************
 * FUNCTION 명 : scwin.btn_JaehaejaInfo_SelectHospitalNoPup_onclick
 * FUNCTION 기능설명 : 의료기관번호선택
*******************************************************************************/ 
scwin.btn_JaehaejaInfo_SelectHospitalNoPup_onclick = async function(e)
{
	var v_Flag = "click";
    var v_Param = "";

	v_Param += "v_Hospital_Cd=" + dma_JeopsuInfo.get("HOSPITAL_NO");

	var v_HospitalInfo = Array();
	v_HospitalInfo = await za.cfn_GetCheonggugigwanInfo(v_Flag, v_Param);

	if (!com.gfn_IsNull(v_HospitalInfo[0])) {
		dma_JeopsuInfo.set("HOSPITAL_NO", v_HospitalInfo[0]);
		dma_JeopsuInfo.set("HOSPITAL_NM", v_HospitalInfo[1]);

		if (parseInt(dma_JeopsuInfo.get("MINWON_DOC_CD")) >= 2000 && parseInt(dma_JeopsuInfo.get("MINWON_DOC_CD")) <= 2499){
		    dma_JeopsuInfo.set("GWANRI_NO",   v_HospitalInfo[64]); 
		}

		//의료기관관리자사정보 SET (2021.08.24)
		dma_JeopsuInfo.set("HOSPITAL_GWANRI_JISA_CD", v_HospitalInfo[38]);
		dma_JeopsuInfo.set("HOSPITAL_GWANRI_JISA_NM", v_HospitalInfo[39]);		

		//플랫폼사업장인 경우 의료기관 관리지사 비교 (2021.08.24)
		if (dma_JeopsuInfo.get("FLATFORM_SAEOPJANG_YN") == "Y" ) {
			if (dma_JeopsuInfo.get("HOSPITAL_GWANRI_JISA_CD") != com.gfn_SsJisaCd()) {
				await com.gfn_MsgAlert("MQAA048");
			}
		}		
	} 

	chk_JaehaejaInfo_bijijeongHospitalYn.setValue("N");
	edt_chk_JaehaejaInfo_bijijeongHospitalYn.setValue("");
}

