		var v_Param = "";

		mae_JaehaejaInfo_hospitalNo.commit();
		v_Param += "v_Hospital_Cd=" + dma_JeopsuInfo.get("HOSPITAL_NO");

		var v_HospitalInfo = Array();
		v_HospitalInfo = await za.cfn_GetCheonggugigwanInfo(v_Flag, v_Param);

		if (!com.gfn_IsNull(v_HospitalInfo[0])){
			dma_JeopsuInfo.set("HOSPITAL_NO", v_HospitalInfo[0]);
			dma_JeopsuInfo.set("HOSPITAL_NM", v_HospitalInfo[1]);
			if (parseInt(dma_JeopsuInfo.get("MINWON_DOC_CD")) >= 2000 && parseInt(dma_JeopsuInfo.get("MINWON_DOC_CD")) <= 2499){
				dma_JeopsuInfo.set("GWANRI_NO", v_HospitalInfo[64]); 
			}

			//의료기관관리자사정보 SE (2021.08.24)
			dma_JeopsuInfo.set("HOSPITAL_GWANRI_JISA_CD", v_HospitalInfo[38]);
			dma_JeopsuInfo.set("HOSPITAL_GWANRI_JISA_NM", v_HospitalInfo[39]);

			//플랫폼사업장인 경우 의료기관 관리지사 비교 (2021.08.24)
			if(dma_JeopsuInfo.get("FLATFORM_SAEOPJANG_YN") == "Y" ){
				if(dma_JeopsuInfo.get("HOSPITAL_GWANRI_JISA_CD") != com.gfn_SsJisaCd()){
