			chk_JaehaejaInfo_bijijeongHospitalYn.setValue("N");
			edt_chk_JaehaejaInfo_bijijeongHospitalYn.setValue("");
		} else {
			mae_JaehaejaInfo_hospitalNo.focus();
		}
	}
}

