/*******************************************************************************
 * FUNCTION 명 : scwin.btn_DamdangjaInfo_DamdangjaJijeong_OnClick
 * FUNCTION 기능설명 : 담당자지정 
*******************************************************************************/ 
scwin.btn_DamdangjaInfo_DamdangjaJijeong_OnClick = function(e) {
    // 2010-08-25 수정 
    if (!com.gfn_IsNull(dma_JeopsuInfo.get("JEOPSU_NO")))  {
        return ; 
    }

    dma_DamdangjaJeopsuInfo.setEmptyValue(); 

	if (com.gfn_IsNull(dma_JeopsuInfo.get("CHEORI_JISA_CD"))) {
	    dma_JeopsuInfo.set("CHEORI_JISA_CD", com.gfn_SsJisaCd());
	}

	//dma_DamdangjaJeopsuInfo.CopyRow(0, "dma_JeopsuInfo", 0);
	dma_DamdangjaJeopsuInfo.setJSON(dma_JeopsuInfo.getJSON());	
	dlt_DamdangjaInfo.removeAll();
	dlt_DamdangjaInfo.setRowJSON(0, dma_DamdangjaJeopsuInfo.getJSON(), false);

	/*
	var srvId		 = "RetrieveBosangDamdangjaCmd";
	var strURL		 = "kcw.q.qa.cmd.RetrieveBosangDamdangjaCmd.do";
	var strinDsList	 = "dma_JeopsuInfo=dma_DamdangjaJeopsuInfo";
	var stroutDsList = "dma_DamdangjaInfo=dma_DamdangjaInfo";
	var strArgument	 = "";
	var strCallback  = "scwin.fn_CallBack";
	*/

	// RetrieveBosangDamdangjaCmd
	com.executeSubmission(sbm_CM0101100M_E006);

    if (!com.gfn_IsNull(dma_DamdangjaInfo.get("USER_NM"))) {

        dma_JeopsuInfo.set("DAMDANGJA_NM", dma_DamdangjaInfo.get("USER_NM"));
		dma_JeopsuInfo.set("DAMDANGJA_ID", dma_DamdangjaInfo.get("USER_ID"));
	}

	// 담당자ID와 최초담당자 ID의 정보가 다를 경우 
	if (com.gfn_IsNull(dma_JeopsuInfo.get("FIRST_DAMDANGJA_ID"))) {
	    dma_JeopsuInfo.set("FIRST_DAMDANGJA_NM", dma_JeopsuInfo.get("DAMDANGJA_NM"));  
		dma_JeopsuInfo.set("FIRST_DAMDANGJA_ID", dma_JeopsuInfo.get("DAMDANGJA_ID"));         
	}

	if (dma_JeopsuInfo.get("DAMDANGJA_ID") != dma_JeopsuInfo.get("FIRST_DAMDANGJA_ID")) {
	    cob_DamdangjaInfo_damdangjaChangeSayuCd.setDisabled(false);
	} else {
		cob_DamdangjaInfo_damdangjaChangeSayuCd.setDisabled(true);
		cob_DamdangjaInfo_damdangjaChangeSayuCd.setValue("");
	}		

	if (dma_JeopsuInfo.get("DAMDANGJA_ID") == "TOTAL"){
	    btn_DamdangjaInfo_DamdangjaJijeong.setDisabled(true);
	}		

}

/*******************************************************************************
 * FUNCTION 명 : scwin.btn_DamdangjaInfo_SelectDamdangjaPup_onclick
 * FUNCTION 기능설명 : 담당자선택 
*******************************************************************************/
scwin.btn_DamdangjaInfo_SelectDamdangjaPup_onclick = async function(e)
{     
    var v_Flag	 = "click";
    var v_Param  = "v_UserId=" + dma_JeopsuInfo.get("DAMDANGJA_ID");
		v_Param += " v_FirstJoheoYn=" + "Y";

    var v_UserInfo = Array();
		v_UserInfo = await com.gfn_GetUserInfo(v_Flag, v_Param);

    if (!com.gfn_IsNull(v_UserInfo[0])) {
		dma_JeopsuInfo.set("DAMDANGJA_NM", v_UserInfo[1]);	
		dma_JeopsuInfo.set("DAMDANGJA_ID", v_UserInfo[0]);
		dma_JeopsuInfo.modifyKeyStatus("DAMDANGJA_ID", true);
		edt_DamdangjaInfoJisa.setValue(v_UserInfo[2]);			 

		// view chanage 로직 일부 이동
		if (dma_JeopsuInfo.get("DAMDANGJA_ID") != dma_JeopsuInfo.get("FIRST_DAMDANGJA_ID")) {
			cob_DamdangjaInfo_damdangjaChangeSayuCd.setDisabled(false);
		} else {
			cob_DamdangjaInfo_damdangjaChangeSayuCd.setDisabled(true);
			cob_DamdangjaInfo_damdangjaChangeSayuCd.setValue("");
		}		

		if (dma_JeopsuInfo.get("DAMDANGJA_ID") == "TOTAL") {
			btn_DamdangjaInfo_DamdangjaJijeong.setDisabled(true);
		}	 

	} else {
		edt_DamdangjaInfo_GeonseolInfo1.focus();
	}	
}

/*******************************************************************************
 * FUNCTION 명 : scwin.edt_DamdangjaInfo_GeonseolInfo1_onkeydown
 * FUNCTION 기능설명 : 담당자선택 
*******************************************************************************/
scwin.edt_DamdangjaInfo_GeonseolInfo1_onkeydown = async function(e)
{
	if (e.keyCode == 13) {		
		edt_DamdangjaInfo_GeonseolInfo1.unbind("onviewchange");

		edt_DamdangjaInfo_GeonseolInfo1.commit();

		//  이벤트 두번 발생하여 주석처리
		var v_Flag = "keyDown";
		var v_Param = "v_UserId=" + dma_JeopsuInfo.get("DAMDANGJA_ID");
		var v_UserInfo = Array();

		v_UserInfo = await com.gfn_GetUserInfo(v_Flag, v_Param);

		if (!com.gfn_IsNull(v_UserInfo[0])) {					
			dma_JeopsuInfo.set("DAMDANGJA_NM", v_UserInfo[1]);	
			dma_JeopsuInfo.set("DAMDANGJA_ID", v_UserInfo[0]);
			dma_JeopsuInfo.modifyKeyStatus("DAMDANGJA_ID", true);
			edt_DamdangjaInfoJisa.setValue(v_UserInfo[2]);			
		} 
		edt_DamdangjaInfo_GeonseolInfo1.bind("onviewchange", scwin.edt_DamdangjaInfo_GeonseolInfo1_onviewchange);		
	}
}

