/*******************************************************************************
 * FUNCTION 명 : scwin.btn_Save_onclick
 * FUNCTION 기능설명 : 보상민원접수 저장 
*******************************************************************************/
scwin.btn_Save_onclick = async function(e) 
{	
	debugger;
	var vGrids = [dma_JeopsuInfo];

	if (!com.gfn_IsUpdatedDataset(vGrids)) 
	{
		await com.gfn_MsgAlert("MZZA015");	// 변경된 내용이 없습니다.
		edt_JeopsuInfo_minwonDocCd.focus();
		return;
	}	

	//저장이벤트 발생시 기본적으로 세팅 	
	$p.parent().scwin.fn_SubSaveEvtSet(dma_JeopsuInfo);	  

	//E-mail 병합 
	$p.parent().scwin.fn_SubEmailSet(dma_JeopsuInfo, scwin.v_EmailcolNms, "Merge");

	var v_MsgArray = Array();		
	//민원서류코드, 민원서류명, 접수일자, 민원인명 필수 (체크사항 1)
	if (com.gfn_IsNull(dma_JeopsuInfo.get("MINWON_DOC_CD"))) {
		v_MsgArray[0] = "민원서류코드";
		await com.gfn_MsgAlert("MZZA068", v_MsgArray);

		edt_JeopsuInfo_minwonDocCd.focus();
		return;
	}

	if (com.gfn_IsNull(dma_JeopsuInfo.get("MINWON_DOC_NM"))) {
		v_MsgArray[0] = "민원서류명";
		await com.gfn_MsgAlert("MZZA068", v_MsgArray);

		edt_JeopsuInfo_minwonDocCd.focus();
		return;
	}

	var v_IlsiMsg = Array(); 
	if (com.gfn_IsNull(dma_JeopsuInfo.get("JEOPSU_ILSI")) || com.length(dma_JeopsuInfo.get("JEOPSU_ILSI")) != 12) {
	    v_IlsiMsg[0] = "접수일시";
	    await com.gfn_MsgAlert("MZZA018", v_IlsiMsg);

	    edt_JeopsuInfo_jeopsuIlsi.focus();
	    return ;
	}else{
		var v_MsgArr1 = Array();     

	    if (parseFloat(dma_JeopsuInfo.get("JEOPSU_ILSI")) > parseFloat(com.substr(com.gfn_GetDate(), 0, 12))) {
			v_MsgArr1[0] = "접수일시"; 
			v_MsgArr1[1] = "현재일시"; 
			await com.gfn_MsgAlert("MZZA048", v_MsgArr1);

			edt_JeopsuInfo_jeopsuIlsi.focus();  
			return ; 
		}

	    if (com.gfn_IsNull(dma_JeopsuInfo.get("JEOPSU_NO"))) {
			if (parseFloat(com.substr(dma_JeopsuInfo.get("JEOPSU_ILSI"), 0, 8)) < parseFloat(com.addDate(com.substr(com.gfn_GetDate(), 0, 8), -90))) {
				await com.gfn_MsgAlert("MQAA009");

				edt_JeopsuInfo_jeopsuIlsi.focus();
				return ;
			}
		}

		if (parseFloat(com.substr(dma_JeopsuInfo.get("JEOPSU_ILSI"), 0, 8)) < parseFloat(dma_JeopsuInfo.get("JAEHAE_DT"))) {
		    v_MsgArr1[0] = "재해일자"; 
			v_MsgArr1[1] = "접수일자"; 
			await com.gfn_MsgAlert("MZZA077", v_MsgArr1);
			dma_JeopsuInfo.set("JAEHAE_DT", "");

			return ; 
		}
	}	

	if (com.gfn_IsNull(dma_JeopsuInfo.get("MINWONIN_NM"))) {
		v_MsgArray[0] = "민원인명";
		await com.gfn_MsgAlert("MZZA068", v_MsgArray);

		edt_MinwoninInfo_minwoninNm.focus();
		return;
	}

	if (com.gfn_IsNull(dma_JeopsuInfo.get("DAMDANGJA_ID"))) {
		v_MsgArray[0] = "담당자ID";
		await com.gfn_MsgAlert("MZZA068", v_MsgArray);

		edt_DamdangjaInfo_GeonseolInfo1.focus();
		return;
	}	

	if (com.gfn_IsNull(dma_JeopsuInfo.get("DAMDANGJA_NM"))) {
		v_MsgArray[0] = "담당자명";
		await com.gfn_MsgAlert("MZZA068", v_MsgArray);

		edt_DamdangjaInfo_GeonseolInfo1.focus();
		return;
	}				

	var v_MinwonDocCd = dma_JeopsuInfo.get("MINWON_DOC_CD");
	if (v_MinwonDocCd == "1081") {
		if (com.gfn_IsNull(dma_JeopsuInfo.get("MINWONIN_RGNO"))) {
			v_MsgArray[0] = "주민등록번호";
			await com.gfn_MsgAlert("MZZA068", v_MsgArray);

			mae_MinwoninInfo_minwoninRgno.focus();
			return;
		}
	}

	/* 진료비 요청사항으로 민원서류코드 2001 ~ 2499 에 해당하는 서식 제외 - 추후 수정될 소지 있음 */ 
	if (parseInt(v_MinwonDocCd) >= 2001 && parseInt(v_MinwonDocCd) <= 2499) {
		if (v_MinwonDocCd == "2018"){
		    if (com.gfn_IsNull(dma_JeopsuInfo.get("JAEHAEJA_RGNO"))) {
				v_MsgArray[0] = "재해자주민등록번호";
				await com.gfn_MsgAlert("MZZA068", v_MsgArray);

				mae_JaehaejaInfo_jaehaejaRgno.focus();
				return;
			}

			if (com.gfn_IsNull(dma_JeopsuInfo.get("JAEHAE_DT"))) {
				v_MsgArray[0] = "재해일자";
				await com.gfn_MsgAlert("MZZA068", v_MsgArray);

				cal_JaehaejaInfo_jaehaeDt.focus();
				return;
			}
		}
	} else {
		/* 2011-03-30 재활 '2645','2641'(심리재활 운용비용지급처리)추가 김성근*/
		if (v_MinwonDocCd != "1017" && v_MinwonDocCd != "1019" && v_MinwonDocCd != "1020"  
		 && v_MinwonDocCd != "1021" && v_MinwonDocCd != "1060"  
		 && v_MinwonDocCd != "1023" && v_MinwonDocCd != "2584" 
		 && v_MinwonDocCd != "1511" && v_MinwonDocCd != "1566" 
		 && v_MinwonDocCd != "1505" && v_MinwonDocCd != "9005" 
		 && v_MinwonDocCd != "9006" && v_MinwonDocCd != "2507" 
		 && v_MinwonDocCd != "2508" && v_MinwonDocCd != "2515" && v_MinwonDocCd != "2516" && v_MinwonDocCd != "2518" && v_MinwonDocCd != "2520" 
		 && v_MinwonDocCd != "2533" && v_MinwonDocCd != "2534" && v_MinwonDocCd != "2540" && v_MinwonDocCd != "2541" 
		 && v_MinwonDocCd != "2542" && v_MinwonDocCd != "2538" && v_MinwonDocCd != "2567" && v_MinwonDocCd != "1014" && v_MinwonDocCd != "2571" 
		 && v_MinwonDocCd != "2572" && v_MinwonDocCd != "2000" && v_MinwonDocCd != "1058" && v_MinwonDocCd != "1059" && v_MinwonDocCd != "1016" 
		 && v_MinwonDocCd != "1010" // 2014.11.28 추가
		 && v_MinwonDocCd != "1083" // 산재전문의사 운영신청서(2018.09.06 추가)
		 && v_MinwonDocCd != "1081" // 2018.09.20 eds_lcs
		 // 2010-08-25 수정 
		 && v_MinwonDocCd != "2662" && v_MinwonDocCd != "2645" && v_MinwonDocCd != "2641")
	    {
		    if (com.gfn_IsNull(dma_JeopsuInfo.get("JAEHAEJA_RGNO"))) {
				v_MsgArray[0] = "재해자주민등록번호";
				await com.gfn_MsgAlert("MZZA068", v_MsgArray);

				mae_JaehaejaInfo_jaehaejaRgno.focus();
				return;
			}

			if (com.gfn_IsNull(dma_JeopsuInfo.get("JAEHAE_DT"))) {
				v_MsgArray[0] = "재해일자";
				await com.gfn_MsgAlert("MZZA068", v_MsgArray);

				cal_JaehaejaInfo_jaehaeDt.focus();
				return;
			}
		}
	}

	if (v_MinwonDocCd == "2586") {
		if (com.gfn_IsNull(dma_JeopsuInfo.get("JAEHAEJA_RGNO"))) {
			v_MsgArray[0] = "재해자주민등록번호";
			await com.gfn_MsgAlert("MZZA068", v_MsgArray);

			mae_JaehaejaInfo_jaehaejaRgno.focus();
			return;
		}
	}

	/* 진료비 요청사항으로 민원서류코드 2001 ~ 2499 에 해당하는 서식은 위 규정을 무시하고 의료기관을 필수로 체크  - 추후 수정될 소지 있음 */ 
	// 2010-08-26 수정 
	// 산재전문의사 임명 및 해임 처리(2018.09.20 추가) eds_lcs
	if ((parseInt(v_MinwonDocCd) >= 2001 && parseInt(v_MinwonDocCd) <= 2499) || v_MinwonDocCd == "1019" || v_MinwonDocCd == "1020" || v_MinwonDocCd == "1083" || v_MinwonDocCd == "1081" || //산재전문의사 운영신청서(2018.09.06 추가) 
	    v_MinwonDocCd == "1058" || v_MinwonDocCd == "1059" || v_MinwonDocCd == "1060" ) {
		if (com.gfn_IsNull(dma_JeopsuInfo.get("HOSPITAL_NO"))) {
			 v_MsgArray[0] = "의료기관번호";
			 await com.gfn_MsgAlert("MZZA068", v_MsgArray);

			 mae_JaehaejaInfo_hospitalNo.focus();
			 return;
		 }
	}

	if (dma_JeopsuInfo.get("MINWONIN_NM") == dma_JeopsuInfo.get("JAEHAEJA_NM") &&
	    dma_JeopsuInfo.get("MINWONIN_RGNO") == dma_JeopsuInfo.get("JAEHAEJA_RGNO") && 
	    dma_JeopsuInfo.get("MINWONIN_GWANGYE_CD") != "01") {
		await com.gfn_MsgAlert("MQAA062", v_MsgArray);

		cob_MinwoninInfo_minwoninGwangyeCd.focus();
		return;
	}		  

	//‘1524', ‘1525', ‘1526', ‘1523', ‘1533', ‘1547', ‘1550' 민원서류코드 : 민원인관계(01)가 본인이 될수 없음(체크사항 4)
	if (v_MinwonDocCd == "1524" || v_MinwonDocCd == "1525" || v_MinwonDocCd == "1526" || v_MinwonDocCd == "1523" 
	 || v_MinwonDocCd == "1533" || v_MinwonDocCd == "1547" || v_MinwonDocCd == "1550" || v_MinwonDocCd == "3614" || v_MinwonDocCd == "1534" )
	{
		if (dma_JeopsuInfo.get("MINWONIN_GWANGYE_CD") == "01") {
			v_MsgArray[0] = v_MinwonDocCd;
			await com.gfn_MsgAlert("MQAA022", v_MsgArray);

			cob_MinwoninInfo_minwoninGwangyeCd.focus();
			return;
		}else if(dma_JeopsuInfo.get("MINWONIN_NM") == dma_JeopsuInfo.get("JAEHAEJA_NM") &&
			dma_JeopsuInfo.get("MINWONIN_RGNO") == dma_JeopsuInfo.get("JAEHAEJA_RGNO")){
			v_MsgArray[0] = v_MinwonDocCd;

			await com.gfn_MsgAlert("MQAA022", v_MsgArray);
			return;
		}		
	} else {
		/*
		 * 1524', ‘1525', ‘1526', ‘1523', ‘1533', ‘1547', ‘1550' 이외 민원서류코드(체크사항 5)
		 * 진료비 요청사항(약국관련)
		 * 2011-03-30 재활 '2645', '2641'(심리재활 운용비용지급처리)추가 김성근
		 */
		if (v_MinwonDocCd != "2000" && v_MinwonDocCd != "2001" && v_MinwonDocCd != "2002" && v_MinwonDocCd != "9005" && v_MinwonDocCd != "9006" && 
		    v_MinwonDocCd != "1016" && v_MinwonDocCd != "2645" && v_MinwonDocCd != "2641")
		{
			if (dma_JeopsuInfo.get("MINWONIN_GWANGYE_CD") == "01")
			{
				if (dma_JeopsuInfo.get("MINWONIN_NM") != dma_JeopsuInfo.get("JAEHAEJA_NM") ||
				    dma_JeopsuInfo.get("MINWONIN_RGNO") != dma_JeopsuInfo.get("JAEHAEJA_RGNO")) {
					v_MsgArray[0] = "민원인 관계가 본인이므로 민원인의 성명, 주민번호";
					v_MsgArray[1] = "재해근로자의 성명, 주민번호"; 
					await com.gfn_MsgAlert("MZZA121", v_MsgArray);

					cob_MinwoninInfo_minwoninGwangyeCd.focus();
					return;
				}
			}
		}
	}

	/*
	 * 2583',‘2585',‘2586',‘2556',‘2512',‘2505',‘2506',‘2573',‘3300' 이외의 민원서류코드(체크사항 6)
	 * 2010-02-02 추가 진료비 요청사항(약국관련)
	 * 2011-03-30 재활 '2645', '2641'(심리재활 운용비용지급처리)추가 김성근
	*/
	if (v_MinwonDocCd != "2583" && v_MinwonDocCd != "2585" && v_MinwonDocCd != "2586" && v_MinwonDocCd != "2556" &&
		v_MinwonDocCd != "2512" && v_MinwonDocCd != "2505" && v_MinwonDocCd != "2506" && v_MinwonDocCd != "2573" &&
		v_MinwonDocCd != "3300" && v_MinwonDocCd != "1014" && v_MinwonDocCd != "9005" && v_MinwonDocCd != "9006" &&
		v_MinwonDocCd != "2000" && v_MinwonDocCd != "2001" && v_MinwonDocCd != "2002" && v_MinwonDocCd != "2645" && 
		v_MinwonDocCd != "2641" ) 
	{
