		    dma_JeopsuInfo.set("JISA_CHK_FG", "1"); 
			//의료기관관리지사와 사용자 소속지사가 동일해야 수정 가능
			if (dma_JeopsuInfo.get("HOSPITAL_GWANRI_JISA_CD") != com.gfn_SsJisaCd() &&
			   (v_MinwonDocCd != "2558" && v_MinwonDocCd != "2555" && v_MinwonDocCd != "2562" && v_MinwonDocCd != "2563" &&
			    v_MinwonDocCd != "2622" && v_MinwonDocCd != "2624" && v_MinwonDocCd != "2649" && v_MinwonDocCd != "2650" &&
			    v_MinwonDocCd != "2708" )			
			  )
			 {
				dma_JeopsuInfo.set("JISA_CHK_FG", "");
				await com.gfn_MsgAlert("MQAA019");
				return;
			 }
		}

		// 사용자의 소속지사코드와 접수된 민원접수번호상의 지사코드가 일치해야만 수정 가능
		if (com.gfn_SsJisaCd() != com.substr(dma_JeopsuInfo.get("JEOPSU_NO"), 0, 4))
		{					
			dma_JeopsuInfo.set("JISA_CHK_FG", "");
			await com.gfn_MsgAlert("MQAA019");
			return;
		}

		// 담당자 지사코드와 접수된 민원접수번호상의 지사코드가 일치해야만 수정 가능
		if (!com.gfn_IsNull(edt_DamdangjaInfoJisa.getValue()) && edt_DamdangjaInfoJisa.getValue() != com.substr(dma_JeopsuInfo.get("JEOPSU_NO"), 0, 4))
		{					
			dma_JeopsuInfo.set("JISA_CHK_FG", "");
			await com.gfn_MsgAlert("MQAA019");
			return;
		}

		//수정 후 민원서류코드가 1701, 1706인 경우 접수일자가 2024.01.22 이전인경우 수정 불가 2024.01.20 허세희
		if (v_MinwonDocCd == "1701" || v_MinwonDocCd == "1706") {
			if (dma_JeopsuInfo.get("JEOPSU_ILSI") < "20240122000000") {
				await com.gfn_Alert("해당민원서류는 민원코드 변경이 불가능합니다.");
				return ; 
			}			
		}

		if (v_MinwonDocCd == "1513") {
			if(dma_JeopsuInfo.get("JEOPSU_ILSI") < "20240122000000") {
				dma_JeopsuInfo.set("PROGRAM_ID", "AA2401");
			}
		}

	  	/*	
		var srvId		 = "UpdateBosangMinwonJeopsuCmd";
		var strURL		 = "kcw.q.qa.cmd.UpdateBosangMinwonJeopsuCmd.do";
		var strinDsList	 = "dma_JeopsuInfo=dma_JeopsuInfo";
		var stroutDsList = "dma_JeopsuInfo=dma_JeopsuInfo";
		var strArgument	 = "";
		var strCallback  = "scwin.fn_CallBack";
		*/

		var vGrids = Array();
		vGrids = [dma_JeopsuInfo];
		if (!com.gfn_IsUpdatedDataset(vGrids)) {
			await com.gfn_MsgAlert("MZZA015");
			return;
		}

		//E-mail 병합 
		$p.parent().scwin.fn_SubEmailSet(dma_JeopsuInfo, scwin.v_EmailcolNms, "Merge");

		// 민원접수 수정
		// UpdateBosangMinwonJeopsuCmd
		com.executeSubmission(sbm_CM0101100M_E004);
	}
}

/*******************************************************************************
 * FUNCTION 명 : scwin.btn_Jeopsujeung_onclick
 * FUNCTION 기능설명 : 접수증을 출력
*******************************************************************************/
scwin.btn_Jeopsujeung_onclick = function(e) {

    // 리포트 초기화
	var ozr = "/cm/cm01/0101/CM0101100R_02.ozr";
    var odi = "CM0101100R_02";

    var formParam = com.gfn_GetReportParam(odi,this);
		formParam += gcm.REPORT_VAL.gv_ozColSep + "GV_FAXBALSONG=3";		    

    var odiParam = 	"JEOPSU_NO="+ dma_JeopsuInfo.get("JEOPSU_NO");
		odiParam += gcm.REPORT_VAL.gv_ozColSep + "MINWON_FG=" + dma_JeopsuInfo.get("MINWON_FG");

	if (dma_JeopsuInfo.get("MINWON_FG") == "1") {
		odiParam += gcm.REPORT_VAL.gv_ozColSep + "ALIAS_NAME=aply";
	} else {
		odiParam += gcm.REPORT_VAL.gv_ozColSep + "ALIAS_NAME=mtcc";
	}

    var v_JeopsuNo  = com.substr(dma_JeopsuInfo.get("JEOPSU_NO"), 0, 4) +  "-";
		v_JeopsuNo += com.substr(dma_JeopsuInfo.get("JEOPSU_NO"), 4, 4) + "-";
		v_JeopsuNo += com.substr(dma_JeopsuInfo.get("JEOPSU_NO"), 8, 7);
    var prtOpt = "";                                
    var title = v_JeopsuNo+"_접수증"; //보고서명 

	com.gfn_PrintHuge(gcm.REPORT_VAL.G_PREVIEW_POPUP, ozr, odi, formParam, odiParam, prtOpt, title);	
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_CallBack
 * FUNCTION 기능설명 : 콜백함수
*******************************************************************************/
scwin.fn_CallBack = async function(e) 
{
	debugger;
	var errorCode = com.getResultCode(e);
	// Error 인 경우 후 처리를 하지 않는다
	if(errorCode != 'S'){
		return;
	}

	var srvId = e.id;
	srvId = srvId.substring(srvId.indexOf("sbm_"), srvId.length);
	switch(srvId)
	{
		// 민원접수조회 후처리 
		case "sbm_CM0101100M_E002" : // RetrieveBosangMinwonJeopsuCmd 보상민원 접수조회 
			edt_JeopsuInfo_jeopsuIlsi.setDisabled(true);

			var v_GJJeopsuNo    = dma_JeopsuInfo.get("JEOPSU_NO");
			var v_GJSeunginFG   = "";
			var v_GJMinwonDocCD = dma_JeopsuInfo.get("MINWON_DOC_CD");
			var v_GJMinwonFG    = dma_JeopsuInfo.get("MINWON_FG");

			//공통결재정보 조회 
			var gyeoljaeStatus = $p.parent().gyeoljaeBar.gfn_GtGyeoljaeInfo(v_GJJeopsuNo, v_GJSeunginFG, v_GJMinwonDocCD, v_GJMinwonFG);

			scwin.v_SujeongModeYN = "Y"; //조회 후 수정모드 ON

			$p.parent().scwin.fn_SubEmailSet(dma_JeopsuInfo, scwin.v_EmailcolNms, "Split");
			// dma_JeopsuInfo.ApplyChange();  // 데이터셋 상태 초기화

			scwin.fnc_AfterJohoeSetting(dma_JeopsuInfo.get("MINWON_DOC_CD")); 

			// 집단민원화면연계버튼은 수정모드(조회 후)이면서 민원서류코드가 1001인 경우만 활성화 시킴. 
			if (scwin.v_SujeongModeYN == "Y" && dma_JeopsuInfo.get("MINWON_DOC_CD") == "1001") {
				btn_GibdanMinwonHwamyeonYg.setDisabled(false);
			} else {
				btn_GibdanMinwonHwamyeonYg.setDisabled(true);
			}

			// 고용노동부전자통보버튼은 수정모드(조회 후)이면서 민원서류코드가 1534인 경우만 활성화 시킴. 
			if (scwin.v_SujeongModeYN == "Y" && dma_JeopsuInfo.get("MINWON_DOC_CD") == "1534" && com.gfn_GetDay() >= "20110823") {
				btn_MOEL_Tongbo.setDisabled(false);
			} else {
				btn_MOEL_Tongbo.setDisabled(true);
			}

			if (!com.gfn_IsNull(dma_JeopsuInfo.get("JEOPSU_NO"))) {
				//btn_IdmsImageJohoe.setDisabled(false);
				//btn_YgHwamyeon.setDisabled(false);

				com.gfn_enableRButton("0");
				btn_Jeopsujeung.setDisabled(false);
				btn_GitaCheori.setDisabled(false); 
				btn_Chogihwa.setDisabled(false); 
				btn_Save.setDisabled(false); 

				scwin.v_PMinwonDocCd = dma_JeopsuInfo.get("MINWON_DOC_CD");
				scwin.v_PMinwonDocNm = dma_JeopsuInfo.get("MINWON_DOC_NM");

				$p.parent().scwin.v_PMinwonDocCd = dma_JeopsuInfo.get("MINWON_DOC_CD");
				$p.parent().scwin.v_PMinwonDocNm = dma_JeopsuInfo.get("MINWON_DOC_NM");

				// 2019.07.11 eds_lcs "I"  기타(부지급) 추가
				if (dma_JeopsuInfo.get("JEOPSU_STATUS_CD") == "5" || 
					dma_JeopsuInfo.get("JEOPSU_STATUS_CD") == "7" ||
					dma_JeopsuInfo.get("JEOPSU_STATUS_CD") == "9" ||
					dma_JeopsuInfo.get("JEOPSU_STATUS_CD") == "E" ||
					dma_JeopsuInfo.get("JEOPSU_STATUS_CD") == "I") {

					com.gfn_disableRButton("0");
				}		    

				if (dma_JeopsuInfo.get("ISONG_YN") == "Y") {
			        var v_ArrJisaInfo ; 
			        v_ArrJisaInfo = await com.gfn_GetJisaInfo("keydown", "v_JisaCd=" + com.substr(dma_JeopsuInfo.get("WON_JEOPSU_NO"), 0, 4)); 
			        st_Isong_Yn.setValue(v_ArrJisaInfo[1] + "(접수번호:" + com.substr(dma_JeopsuInfo.get("WON_JEOPSU_NO"), 0, 4) + "-" + com.substr(dma_JeopsuInfo.get("WON_JEOPSU_NO"), 4, 4) + "-" + com.substr(dma_JeopsuInfo.get("WON_JEOPSU_NO"), 8 ) + ")" + "에서 이송된 민원입니다."); 
			    } else {
			        st_Isong_Yn.setValue(""); 
			    }  

			    if (dma_JeopsuInfo.get("DAMDANGJA_ID") != dma_JeopsuInfo.get("FIRST_DAMDANGJA_ID")) {
			        cob_DamdangjaInfo_damdangjaChangeSayuCd.setDisabled(false); 
			    } 

			    if (!com.gfn_IsNull(dma_JeopsuInfo.get("WONBU_NO")))
			    {
					var v_ServiceDaesangInfo = await qa.cfn_GetServiceDaesangInfo(dma_JeopsuInfo.get("WONBU_NO"));
					dma_ServiceDaesangInfo.setEmptyValue();
					dma_ServiceDaesangInfo.set("SERVICE_DAESANG_FG", v_ServiceDaesangInfo[0]);
				}
				else
				{
					dma_ServiceDaesangInfo.setEmptyValue();
				}

				edt_GMJDCd.setValue("");
				var v_GMJD = az.cfn_GetGwagyeokMinwonJeongdo(com.trim(mae_JaehaejaInfo_jaehaejaRgno.getValue()),"");
				edt_GMJDCd.setValue(v_GMJD);
			} else {
				com.gfn_disableRButton("0");
				btn_Jeopsujeung.setDisabled(true);
				btn_GitaCheori.setDisabled(true); 
				btn_Chogihwa.setDisabled(false); 
				btn_Save.setDisabled(true); 

				scwin.v_PMinwonDocCd    = "";
				scwin.v_PMinwonDocNm    = "";
				$p.parent().scwin.v_PMinwonDocCd = "";
				$p.parent().scwin.v_PMinwonDocNm = "";

				st_Isong_Yn.setValue(""); 
			}

			scwin.fnc_MinwonSeosikExCheori(dma_JeopsuInfo.get("MINWON_DOC_CD"));
			dma_JeopsuInfo.reform();
		break;	

		// 보상민원접수저장 후처리 
		case "sbm_CM0101100M_E003" : // "CreateBosangMinwonJeopsuCmd"
		    if (!com.gfn_IsNull(dma_JeopsuInfo.get("JEOPSU_NO"))) {
				var v_msg     = Array();
				var v_Moel    = "" ; 
				var v_tmpStr  = "" ; 
				v_msg[0] = dma_JeopsuInfo.get("JEOPSU_NO");

				v_Moel = await qa.cfn_RetrieveMinwonJeopsuNaeyeok(v_msg[0], "2");

				if (v_Moel[4] == "1534") {
		            //if (com.gfn_Confirm("유족급여(장의비 포함)에 대한 대체지급 청구시에는 요양업무처리규정 제56조 제2항에 의해 반드시 고용노동부에 통보하도록 되어 있습니다. \n통보하시려면 [확인]버튼을 클릭해 주십시오." ) == "1") {
					var conRtn = await com.gfn_Confirm("유족급여(장의비 포함)에 대한 대체지급 청구시에는 요양업무처리규정 제56조 제2항에 의해 반드시 고용노동부에 통보하도록 되어 있습니다. \n통보하시려면 [확인]버튼을 클릭해 주십시오.");
					if (conRtn){ 	

		                scwin.fn_MOEL_Tongbo(v_msg[0], v_Moel[4]); 
		            }
		        }

				// 재조회		
				scwin.fn_RetrieveMinwonJeopsuInfo(dma_JeopsuInfo.get("JEOPSU_NO"));

				await com.gfn_MsgStatus("MQAA020", v_msg);
			}		
		break;

		// 보상민원접수수정 후처리
		case "sbm_CM0101100M_E004" : //	"UpdateBosangMinwonJeopsuCmd"
			if (!com.gfn_IsNull(dma_JeopsuInfo.get("JEOPSU_NO"))) {
				var v_msg = Array();
				v_msg[0] = dma_JeopsuInfo.get("JEOPSU_NO");

				// 재조회		
				scwin.fn_RetrieveMinwonJeopsuInfo(dma_JeopsuInfo.get("JEOPSU_NO"));

				com.gfn_MsgStatus("MQAA020", v_msg);
			}		
		break;

		// 고용노동부전자통보 후처리
		case "sbm_CM0101100M_E007"	: // "CreateBosangMinwonMOELJeonsongCmd"	:			
			await com.gfn_Alert("고용노동부전자통보가 정상처리 되었습니다."); 
			btn_MOEL_Tongbo.setDisabled(true);
		break;		
	}
}

/*******************************************************************************
 * FUNCTION 명 : scwin.dma_JeopsuInfo_onbeforemodelchange
 * FUNCTION 기능설명 : dma_JeopsuInfo 특정 key 에 대한 value 값 변경전 발생이벤트
*******************************************************************************/
scwin.dma_JeopsuInfo_onbeforemodelchange = async function(info)
{
	var varOldValue = info.oldValue;
	var varNewValue = info.newValue;
	var strColumnID = info.key;

	// 민원서류코드선택 
	if (strColumnID == "MINWON_DOC_CD") {
		/*
		//접수구분이 전화상담접수(9)일 경우 
		if (scwin.v_SujeongModeYN == "Y" && dma_JeopsuInfo.get("JEOPSU_FG") == "9") {
			await com.gfn_MsgAlert("MQAA007");
			return false;
		}

		// 조회조건의 민원구분변경시 메세지처리
		var rev = $p.parent().scwin.fn_SubUpdateCheckMinwonDocCd(varNewValue);
		if (!rev) {
			dma_JeopsuInfo.set("MINWON_DOC_CD", varOldValue);
			return false;
		}
		*/
	}

	//접수일시수정 
	if (strColumnID == "JEOPSU_ILSI") {
		//
	}

	//재해일자수정 
	if (strColumnID == "JAEHAE_DT") {
		var v_changeJeopsuIlsiMsg = Array();		
		if (varNewValue > dma_JeopsuInfo.get("JEOPSU_ILSI")) {

			v_changeJeopsuIlsiMsg[0] = "재해일자";
			v_changeJeopsuIlsiMsg[1] = "접수일자";
			await com.gfn_MsgAlert("MZZA077", v_changeJeopsuIlsiMsg);

			dma_JeopsuInfo.set("JAEHAE_DT", varOldValue);			
			cal_JaehaejaInfo_jaehaeDt.focus();

			return false;
		}
	}

	// 민원인관계선택변경 
	if (strColumnID == "MINWONIN_GWANGYE_CD") {		
		var v_MinwonDocCd = dma_JeopsuInfo.get("MINWON_DOC_CD");
		if (v_MinwonDocCd == "1524" || v_MinwonDocCd == "1525" || v_MinwonDocCd == "1526" || v_MinwonDocCd == "1523" || v_MinwonDocCd == "1534") { 
			if (varNewValue == "01") {
				var v_MsgArray = Array();
				v_MsgArray[0] = v_MinwonDocCd;
				await com.gfn_MsgAlert("MQAA022", v_MsgArray);

				// 이전 코드로
				dma_JeopsuInfo.set("MINWONIN_GWANGYE_CD", varOldValue);
				return false;
			}
		}
	}
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fnc_AfterJohoeSetting
 * FUNCTION 기능설명 : 민원서류코드에 따른 세팅
*******************************************************************************/
scwin.fnc_AfterJohoeSetting = function(varMinwonDocCd)
{
    if (varMinwonDocCd == "1017") {
	    mae_JaehaejaInfo_hospitalNo.setDisabled(true); 
		btn_JaehaejaInfo_SelectHospitalNoPup.setDisabled(true); 
	} else {
		mae_JaehaejaInfo_hospitalNo.setDisabled(false); 
		btn_JaehaejaInfo_SelectHospitalNoPup.setDisabled(false); 
	}

	//화면의 재해일자 항목이 진단일자로 바뀌는 경우 
	if (varMinwonDocCd == "3600" || varMinwonDocCd == "3601" || varMinwonDocCd == "3602" || 
		varMinwonDocCd == "3603" || varMinwonDocCd == "3623" || varMinwonDocCd == "3611" ||
		varMinwonDocCd == "3612" || varMinwonDocCd == "3627" )
	{
		st_JaehaejaInfo_tb115_h_jaehaeDt.setValue("진단일자");
		st_JaehaejaInfo_tb115_h_jaehaeDt.setValue("진단일자");
	} else if( varMinwonDocCd == "3634") {
	    st_JaehaejaInfo_tb115_h_jaehaeDt.setValue("검진일자");
		st_JaehaejaInfo_tb115_h_jaehaeDt.setValue("검진일자");
	} else {
		st_JaehaejaInfo_tb115_h_jaehaeDt.setValue("재해일자");
		st_JaehaejaInfo_tb115_h_jaehaeDt.setValue("재해일자");
	}

	// 2018.09.20 eds_lcs 
	if (varMinwonDocCd == "1081") {
		st_MinwoninInfo_tb113_h_minwoninRgno.setStyle("class", "req");
		//st_MinwoninInfo_tb113_h_minwoninRgno.Color  = "user31";
    } else {
		st_MinwoninInfo_tb113_h_minwoninRgno.setStyle("class", "");
		//st_MinwoninInfo_tb113_h_minwoninRgno.Color  = "user0";
    }

	//의료기관번호가 입력불가인 코드 :  1017, 1504, 1505, 1524, 1525, 1526
	if (varMinwonDocCd == "1017" || varMinwonDocCd == "1504" || varMinwonDocCd == "1505" || varMinwonDocCd == "1524" ||
	    varMinwonDocCd == "1525" || varMinwonDocCd == "1526") {
	    mae_JaehaejaInfo_hospitalNo.setDisabled(true);

		//이 중 1017, 1505를 제외하고 나머지는 재해근로자주민등록 번호, 재해일자가 입력필수항목이 된다
		if (varMinwonDocCd != "1017" && varMinwonDocCd != "1505") {
	 	   //mae_JaehaejaInfo_jaehaejaRgno.UserData = "optional=required";
		   //cal_JaehaejaInfo_jaehaeDt.UserData = "minLength=8;optional=required";
		   mae_JaehaejaInfo_jaehaejaRgno.setMandatory(true);
		   cal_JaehaejaInfo_jaehaeDt.setMandatory(true);
		   cal_JaehaejaInfo_jaehaeDt.setStyle("minLength", 8);
		} else {
		   //mae_JaehaejaInfo_jaehaejaRgno.UserData = "";
		   //cal_JaehaejaInfo_jaehaeDt.UserData = "minLength=8";
		   mae_JaehaejaInfo_jaehaejaRgno.setMandatory(false);
		   cal_JaehaejaInfo_jaehaeDt.setMandatory(false);
		   cal_JaehaejaInfo_jaehaeDt.setStyle("minLength", 8);
		}
	} else {
		mae_JaehaejaInfo_hospitalNo.setDisabled(false);
	}    
}

