	edt_JaehaejaInfo_addr3.setDisabled(!enableFg);
	edt_JaehaejaInfo_telNo.setDisabled(!enableFg);
	edt_JaehaejaInfo_telNo2.setDisabled(!enableFg);
	edt_JaehaejaInfo_telNo4.setDisabled(!enableFg);
	edt_JaehaejaInfo_hpNo.setDisabled(!enableFg);
	edt_JaehaejaInfo_hpNo2.setDisabled(!enableFg);
	edt_JaehaejaInfo_hpNo4.setDisabled(!enableFg);
	edt_JaehaejaInfo_jaehaejaEmail.setDisabled(!enableFg);
	edt_JaehaejaInfo_jaehaejaEmailDomain.setDisabled(!enableFg);
	edt_JaehaejaInfo_jaehaejaEmailCombo.setDisabled(!enableFg);
}

/*******************************************************************************
 * FUNCTION 명 : scwin.dma_JeopsuInfo_onmodelchange
 * FUNCTION 기능설명 : dma_JeopsuInfo 데이터셋 변경 후 발생 이벤트
*******************************************************************************/
scwin.dma_JeopsuInfo_onmodelchange = async function(info)
{
	var varOldValue = info.oldValue;
	var varNewValue = info.newValue;
	var strColumnID = info.key;

	//민원서류코드선택 
	if (strColumnID == "MINWON_DOC_CD") {

	    var v_GihanArr; 	
	    if (com.gfn_IsNull(dma_JeopsuInfo.get("JEOPSU_NO"))) {
			// 메시지 겹침 현상으로 이동
			/*
            if (!com.gfn_IsNull(dma_JeopsuInfo.get("MINWON_DOC_CD")) && com.length(com.trim(dma_JeopsuInfo.get("MINWON_DOC_CD"))) == 4 ) {
                v_GihanArr = await scwin.fn_RetrieveMinwonCheoriGihan(); 

	            if (!com.gfn_IsNull(v_GihanArr[0])) {
	                dma_JeopsuInfo.set("CHEORI_GIHAN", v_GihanArr[0]); 
	            }
            } else {
	            dma_JeopsuInfo.set("CHEORI_GIHAN", ""); 
	        }
			*/
	    }        

		/* 2010-03-23 add 재활 요청*/
		if (varNewValue == "2584")	//직업훈련비용 청구서
		{
			scwin.fn_SetJaehaejaInfoEnalble(false);
		} else {
			scwin.fn_SetJaehaejaInfoEnalble(true);
		}

		/* 진료비 요청사항으로 민원서류코드 2001 ~ 2499 은 민원인관계가 의료기관 (13) */ 
		if (parseInt(varNewValue) >= 2000 && parseInt(varNewValue) <= 2499 ){	
		    scwin.v_MinGwangyeCd = "13";
			dma_JeopsuInfo.set("MINWONIN_GWANGYE_CD", "13");
			cob_MinwoninInfo_minwoninGwangyeCd.commit();
		} else {
			scwin.v_MinGwangyeCd = "";
		}

		if (varNewValue == "1524" || varNewValue == "1525" || varNewValue == "1526" || varNewValue == "1523") {
			scwin.v_MinGwangyeCd = "03"; 
		    dma_JeopsuInfo.set("MINWONIN_GWANGYE_CD", "03"); 
			cob_MinwoninInfo_minwoninGwangyeCd.commit();
		} else if(varNewValue == "1534") {
			scwin.v_MinGwangyeCd = "08"; 
		    dma_JeopsuInfo.set("MINWONIN_GWANGYE_CD", "08"); //민원서류코드 1534일 때 민원인관계->사업장으로 셋팅(2020.6.25.-LEEHW) 
			cob_MinwoninInfo_minwoninGwangyeCd.commit();
		} else {
			scwin.v_MinGwangyeCd = "";
		}

		if (varNewValue == "1017") {

		    mae_JaehaejaInfo_hospitalNo.setDisabled(true); 
		    btn_JaehaejaInfo_SelectHospitalNoPup.setDisabled(true); 
		    dma_JeopsuInfo.set("MINWONIN_GWANGYE_CD", "13");
			cob_MinwoninInfo_minwoninGwangyeCd.commit();
		} else {
		    mae_JaehaejaInfo_hospitalNo.setDisabled(false); 
		    btn_JaehaejaInfo_SelectHospitalNoPup.setDisabled(false); 

		    if (varNewValue == "1019" || varNewValue == "1020" || varNewValue == "1083" || varNewValue == "1081") { //산재전문의사 운영신청서(2018.09.06 추가) 
		        cob_MinwoninInfo_minwoninGwangyeCd.setValue("13"); 
		    } else {
		        // 2010-08-20 
		        if (parseInt(varNewValue) < 2000 || parseInt(varNewValue) > 2499){
		            cob_MinwoninInfo_minwoninGwangyeCd.setValue("01");    
		        }
		    }
		}

		// 화면의 재해일자 항목이 진단일자로 바뀌는 경우 
		if (varNewValue == "3600" || varNewValue == "3601" || varNewValue == "3602" || 
			varNewValue == "3603" || varNewValue == "3623" || varNewValue == "3611" ||
			varNewValue == "3612" || varNewValue == "3627")
		{
			st_JaehaejaInfo_tb115_h_jaehaeDt.setValue("진단일자");
		} else if( varNewValue == "3634" ) {
		    st_JaehaejaInfo_tb115_h_jaehaeDt.setValue("검진일자");
		} else {
			st_JaehaejaInfo_tb115_h_jaehaeDt.setValue("재해일자");
		}

		// 2018.09.20 eds_lcs 
		if (varNewValue == "1081") {
			st_MinwoninInfo_tb113_h_minwoninRgno.Color  = "user31";
		} else {
			st_MinwoninInfo_tb113_h_minwoninRgno.Color  = "user0";
		}

		// 민원서류코드가 "1001"인 경우 "집단민원화면연계" 버튼을 활성화 
		if (varNewValue == "1001") {
			btn_JaehaejaInfo_SelectJaehaejaPup.setDisabled(true);

			if (scwin.v_SujeongModeYN=="Y") {
				btn_GibdanMinwonHwamyeonYg.setDisabled(false);
			} else {
				btn_GibdanMinwonHwamyeonYg.setDisabled(true);
			}
		} else {
			if(varNewValue != "2584")	// 직업훈련비용 청구서 
				btn_JaehaejaInfo_SelectJaehaejaPup.setDisabled(false);
		}

		// 의료기관번호가 입력불가인 코드 :  1017, 1504, 1505, 1524, 1525, 1526
		if (varNewValue == "1017" || varNewValue == "1504" || varNewValue == "1505" || varNewValue == "1524" ||
		    varNewValue == "1525" || varNewValue == "1526") {

		    mae_JaehaejaInfo_hospitalNo.setValue("");
			mae_JaehaejaInfo_hospitalNo.setDisabled(true);

			// 이 중 1017, 1505를 제외하고 나머지는 재해근로자주민등록 번호, 재해일자가 입력필수항목이 된다
			if (varNewValue != "1017" && varNewValue != "1505") {
				//mae_JaehaejaInfo_jaehaejaRgno.UserData = "optional=required";
				//cal_JaehaejaInfo_jaehaeDt.UserData = "minLength=8;optional=required";
				mae_JaehaejaInfo_jaehaejaRgno.setMandatory(true);
				cal_JaehaejaInfo_jaehaeDt.setMandatory(true);
				cal_JaehaejaInfo_jaehaeDt.setStyle("minlength", 8);
			} else {
				//mae_JaehaejaInfo_jaehaejaRgno.UserData = "";
				//cal_JaehaejaInfo_jaehaeDt.UserData = "minLength=8";

				mae_JaehaejaInfo_jaehaejaRgno.setMandatory(false);
				cal_JaehaejaInfo_jaehaeDt.setMandatory(false);
				cal_JaehaejaInfo_jaehaeDt.setStyle("minlength", 8);
			}
		} else {
			mae_JaehaejaInfo_hospitalNo.setDisabled(false);
		}

		scwin.fn_checkRgnoOrBirthday("CHANGE", varNewValue);

		// 2024.01.09 민원서류 코드 변경에 따른 대리인 정보 필수값 여부 change
		scwin.fn_DaeriinYn_OnChanged();
	}
	//민원인관계선택변경 
	else if (strColumnID == "MINWONIN_GWANGYE_CD")
	{
		//민원인관계 : 노무사(14) || 변호사(15)
		//dma_JeopsuInfo.FireEvent = false;
		dma_JeopsuInfo.unbind("onbeforemodelchange");
		dma_JeopsuInfo.unbind("onmodelchange");
		dma_JeopsuInfo.unbind("onsetdata");

		if (varNewValue == "14" || varNewValue == "15") {
			chk_DaeriinInfo_daeriinSuimYn.setValue("Y");
			cob_DaeriinInfo_daeriinFg.setDisabled(false);
			edt_DaeriinInfo_daeriinNm.setDisabled(false);
			edt_DaeriinInfo_daeriinGaeeopNo.setDisabled(false);

			//민원인관계 노무사(14) 
			if (varNewValue == "14") {
				dma_JeopsuInfo.set("DAERIIN_FG", "2");
				edt_DaeriinInfo_daeriinNm.setValue(edt_MinwoninInfo_minwoninNm.Text);
			}
			//민원인관계 변호사(15) 
			else if (varNewValue == "15") {
				dma_JeopsuInfo.set("DAERIIN_FG", "1");
				edt_DaeriinInfo_daeriinNm.setValue(edt_MinwoninInfo_minwoninNm.Text);
			}
		} else {
			chk_DaeriinInfo_daeriinSuimYn.setValue("N");
			cob_DaeriinInfo_daeriinFg.setDisabled(true);
			edt_DaeriinInfo_daeriinNm.setDisabled(true);
			edt_DaeriinInfo_daeriinNm.setValue("");
			edt_DaeriinInfo_daeriinGaeeopNo.setDisabled(true);
			edt_DaeriinInfo_daeriinGaeeopNo.setValue("");
		}

		//민원인관계를 다른 코드로 변경한 경우 
		if  (varNewValue != varOldValue) {
			//민원인관계가 본인이외의 관계로 변경 될 경우 민원인 정보를 초기화한다.
			// 
		}

		//민원서류코드가 "1524", "1525", "1526", "1523" 이외의 경우 민원인관계가 본인(01)일 경우 민원인정보와 재해근로자정보를 일치시킨다. 
		var v_MinwonDocCd = dma_JeopsuInfo.get("MINWON_DOC_CD");
		if (v_MinwonDocCd != "1524" && v_MinwonDocCd != "1525" && v_MinwonDocCd != "1526" && v_MinwonDocCd != "1523" && v_MinwonDocCd != "1534") {
			if (varNewValue == "01") {
				//dma_JeopsuInfo.FireEvent = false;
				dma_JeopsuInfo.unbind("onbeforemodelchange");
				dma_JeopsuInfo.unbind("onmodelchange");
				dma_JeopsuInfo.unbind("onsetdata");

				scwin.fn_MinwoninSet(true);	

				//dma_JeopsuInfo.FireEvent = true;
				dma_JeopsuInfo.bind("onbeforemodelchange", scwin.dma_JeopsuInfo_onbeforemodelchange);
				dma_JeopsuInfo.bind("onmodelchange"      , scwin.dma_JeopsuInfo_onmodelchange);
				dma_JeopsuInfo.bind("onsetdata"          , scwin.dma_JeopsuInfo_onsetdata);
			}
		}

		//dma_JeopsuInfo.FireEvent = true;
		dma_JeopsuInfo.bind("onbeforemodelchange", scwin.dma_JeopsuInfo_onbeforemodelchange);
		dma_JeopsuInfo.bind("onmodelchange"      , scwin.dma_JeopsuInfo_onmodelchange);
		dma_JeopsuInfo.bind("onsetdata"          , scwin.dma_JeopsuInfo_onsetdata);
	}
	//관리번호 입력 후 
	else if (strColumnID == "GWANRI_NO")
	{   
		if (dma_JeopsuInfo.get("GWANRI_NO").length == "11") {
				var v_SaeopjangInfo = Array();

				var v_Flag  = "keyDown";
				var v_Param = "v_Saeopjang_Gwanri_No=" + dma_JeopsuInfo.get("GWANRI_NO");

				v_SaeopjangInfo = await com.cfn_GetSaeopjangInfo(v_Flag, v_Param);

				// 사업장정보세팅 
				if (!com.gfn_IsNull(v_SaeopjangInfo[2])) {
					//dma_JeopsuInfo.FireEvent = false;
					dma_JeopsuInfo.unbind("onbeforemodelchange");
					dma_JeopsuInfo.unbind("onmodelchange");
					dma_JeopsuInfo.unbind("onsetdata");

					// 사업개시번호 팝업 방지
					mae_SaeopjangInfo_saeopjangGaesiNo.unbind("onviewchange");

					dma_JeopsuInfo.set("GWANRI_NO"				, v_SaeopjangInfo[ 2]);
					if (com.gfn_IsNull(v_SaeopjangInfo[74])) {
		                dma_JeopsuInfo.set("SE_WONBU_NO"		, v_SaeopjangInfo[ 0]);
		            } else {
		                dma_JeopsuInfo.set("SE_WONBU_NO"        , v_SaeopjangInfo[74]);
		            }

					dma_JeopsuInfo.set("SAEOPJA_DRNO"			, v_SaeopjangInfo[12]);
					dma_JeopsuInfo.set("BEOPIN_DRNO"			, v_SaeopjangInfo[13]);
					dma_JeopsuInfo.set("SAEOPJANG_GAESI_NO"		, v_SaeopjangInfo[ 1]);
					dma_JeopsuInfo.set("SAEOPJANG_NM"			, v_SaeopjangInfo[ 3]);
					dma_JeopsuInfo.set("SAEOPJANG_GIBON_ADDR"	, v_SaeopjangInfo[27]);
					dma_JeopsuInfo.set("SAEOPJANG_SANGSE_ADDR"	, v_SaeopjangInfo[28]);
					dma_JeopsuInfo.set("SAEOPJANG_POST"			, v_SaeopjangInfo[26]);
					dma_JeopsuInfo.set("SAEOPJANG_DDD"			, v_SaeopjangInfo[38]);
					dma_JeopsuInfo.set("SAEOPJANG_TEL1"			, v_SaeopjangInfo[39]);
					dma_JeopsuInfo.set("SAEOPJANG_TEL2"			, v_SaeopjangInfo[40]);
					dma_JeopsuInfo.set("SAEOPJANG_FAX_DDD"		, v_SaeopjangInfo[41]);
					dma_JeopsuInfo.set("SAEOPJANG_FAX_TEL1"		, v_SaeopjangInfo[42]);
					dma_JeopsuInfo.set("SAEOPJANG_FAX_TEL2"		, v_SaeopjangInfo[43]);
					dma_JeopsuInfo.set("SAEOPJANG_EMAIL"		, v_SaeopjangInfo[47]);	
					dma_JeopsuInfo.set("SAEOPGAESI_NO"          , v_SaeopjangInfo[ 1]);
					dma_JeopsuInfo.set("GS_WONBU_NO"            , "");
					dma_JeopsuInfo.set("ARTIST_SAEOPJANG_YN"     , v_SaeopjangInfo[78]);  //특수형태근로자 20210615_AM_01  (2021.06.28)
					dma_JeopsuInfo.set("TS_SAEOP_FG"             , v_SaeopjangInfo[79]);  //특수형태근로자 20210615_AM_01  (2021.06.28)
					dma_JeopsuInfo.set("DONGIL_RISK_SE_WONBU_NO" , v_SaeopjangInfo[80]);  //특수형태근로자 20210615_AM_01  (2021.06.28)
					dma_JeopsuInfo.set("BOSANG_GWANRI_JISA_CD"   , v_SaeopjangInfo[81]);  //특수형태근로자 20210615_AM_01  (2021.06.28)
					dma_JeopsuInfo.set("DONGIL_RISK_SE_WONBU_NO_SJ_SAEOP_FG" , v_SaeopjangInfo[82]); //특수형태근로자 20210615_AM_01  (2021.06.28)
					dma_JeopsuInfo.set("DONGIL_RISK_GWANRI_NO"   , v_SaeopjangInfo[83]);  //특수형태근로자 20210615_AM_01  (2021.06.28)
					dma_JeopsuInfo.set("TS_GS_SAEOP_YN"  		 , v_SaeopjangInfo[84]);  //특고개시사업장 유무 (2021.07.19)
					dma_JeopsuInfo.set("FLATFORM_SAEOPJANG_YN"   , v_SaeopjangInfo[85]);  //플랫폼사업장 유무   (2021.08.24)

					//플랫폼개시사업장이면 관리번호에 플랫폼사업장정보 set (2023.11.21)
					if (v_SaeopjangInfo[4] == "C") {
						dma_JeopsuInfo.set("SAEOPJANG_GAESI_NO", "");
						dma_JeopsuInfo.set("SAEOPGAESI_NO"     , "");
						dma_JeopsuInfo.set("GS_WONBU_NO"       , "");
						dma_JeopsuInfo.set("SE_WONBU_NO"       , v_SaeopjangInfo[0]);						
						dma_JeopsuInfo.set("GWANRI_NO"		   , v_SaeopjangInfo[1 ]);
						dma_JeopsuInfo.set("SAEOPJANG_NM"      , v_SaeopjangInfo[17]);
					}

			        await scwin.mae_SaeopjangInfo_saeopjangGaesiNo_onviewchange();

					//특수형태근로자(20210615_AM_01) 인 경우 보상관리지사와 접수지사 상이 여부 체크 (2021.06.28)					
					if (dma_JeopsuInfo.get("TS_SAEOP_FG") == "1") {
						if (v_SaeopjangInfo[81] != com.gfn_SsJisaCd()) {
							await com.gfn_MsgAlert("MQAA048");
						}					
					} else { 
					    //플랫폼사업장인 경우 의료기관 관리지사 비교 (2021.08.24)
						if (dma_JeopsuInfo.get("FLATFORM_SAEOPJANG_YN") == "Y" ) {
							if (!com.gfn_IsNull(dma_JeopsuInfo.get("HOSPITAL_GWANRI_JISA_CD")) && dma_JeopsuInfo.get("HOSPITAL_GWANRI_JISA_CD") != com.gfn_SsJisaCd()) {
								await com.gfn_MsgAlert("MQAA048");
							}
						} else {
							if (v_SaeopjangInfo[51] != com.gfn_SsJisaCd()) {
								await com.gfn_MsgAlert("MQAA048");
							}
						}					
					}

					// dma_JeopsuInfo.FireEvent = true;
					dma_JeopsuInfo.bind("onbeforemodelchange", scwin.dma_JeopsuInfo_onbeforemodelchange);
					dma_JeopsuInfo.bind("onmodelchange"      , scwin.dma_JeopsuInfo_onmodelchange);
					dma_JeopsuInfo.bind("onsetdata"          , scwin.dma_JeopsuInfo_onsetdata);

					// 사업개시번호 팝업 방지
					mae_SaeopjangInfo_saeopjangGaesiNo.bind("onviewchange", "scwin.mae_SaeopjangInfo_saeopjangGaesiNo_onviewchange");

				} else {
				    // dma_JeopsuInfo.FireEvent = false;
					dma_JeopsuInfo.unbind("onbeforemodelchange");
					dma_JeopsuInfo.unbind("onmodelchange");
					dma_JeopsuInfo.unbind("onsetdata");

					// 사업개시번호 팝업 방지
					mae_SaeopjangInfo_saeopjangGaesiNo.unbind("onviewchange");

			        dma_JeopsuInfo.set("SE_WONBU_NO"			 , "");
			        dma_JeopsuInfo.set("SAEOPJA_DRNO"			 , "");
			        dma_JeopsuInfo.set("BEOPIN_DRNO"			 , "");
			        dma_JeopsuInfo.set("SAEOPJANG_GAESI_NO"		 , "");
			        dma_JeopsuInfo.set("SAEOPJANG_NM"			 , "");
			        dma_JeopsuInfo.set("SAEOPJANG_GIBON_ADDR"	 , "");
			        dma_JeopsuInfo.set("SAEOPJANG_SANGSE_ADDR"	 , "");
			        dma_JeopsuInfo.set("SAEOPJANG_POST"			 , "");
			        dma_JeopsuInfo.set("SAEOPJANG_DDD"			 , "");
			        dma_JeopsuInfo.set("SAEOPJANG_TEL1"			 , "");
			        dma_JeopsuInfo.set("SAEOPJANG_TEL2"			 , "");
			        dma_JeopsuInfo.set("SAEOPJANG_FAX_DDD"		 , "");
			        dma_JeopsuInfo.set("SAEOPJANG_FAX_TEL1"		 , "");
			        dma_JeopsuInfo.set("SAEOPJANG_FAX_TEL2"		 , "");
			        dma_JeopsuInfo.set("SAEOPJANG_EMAIL"		 , "");	
			        dma_JeopsuInfo.set("SAEOPGAESI_NO"           , "");
		            dma_JeopsuInfo.set("GS_WONBU_NO"             , "");
		            dma_JeopsuInfo.set("ARTIST_SAEOPJANG_YN"     , "");  //특수형태근로자 20210615_AM_01  (2021.06.28)
		            dma_JeopsuInfo.set("TS_SAEOP_FG"             , "");  //특수형태근로자 20210615_AM_01  (2021.06.28)
		            dma_JeopsuInfo.set("DONGIL_RISK_SE_WONBU_NO" , "");  //특수형태근로자 20210615_AM_01  (2021.06.28)
		            dma_JeopsuInfo.set("BOSANG_GWANRI_JISA_CD"   , "");  //특수형태근로자 20210615_AM_01  (2021.06.28)
		            dma_JeopsuInfo.set("DONGIL_RISK_SE_WONBU_NO_SJ_SAEOP_FG" , ""); //특수형태근로자 20210615_AM_01  (2021.06.28)
		            dma_JeopsuInfo.set("DONGIL_RISK_GWANRI_NO"   , "");  //특수형태근로자 20210615_AM_01  (2021.06.28)
		            dma_JeopsuInfo.set("TS_GS_SAEOP_YN"          , "");  //특고개시사업장 유무 (2021.07.19)
		            dma_JeopsuInfo.set("FLATFORM_SAEOPJANG_YN"   , "");  //플랫폼사업장 유무   (2021.08.24)

			        // dma_JeopsuInfo.FireEvent = true;
					dma_JeopsuInfo.bind("onbeforemodelchange", scwin.dma_JeopsuInfo_onbeforemodelchange);
					dma_JeopsuInfo.bind("onmodelchange"      , scwin.dma_JeopsuInfo_onmodelchange);
					dma_JeopsuInfo.bind("onsetdata"          , scwin.dma_JeopsuInfo_onsetdata);

					// 사업개시번호 팝업 방지
					mae_SaeopjangInfo_saeopjangGaesiNo.bind("onviewchange", "scwin.mae_SaeopjangInfo_saeopjangGaesiNo_onviewchange");

			        mae_JaehaejaInfo_gwanriNo.focus(); 
				}
