/*******************************************************************************
 * FUNCTION 명 : scwin.fn_FromJaehaejaToMinwonin
 * FUNCTION 기능설명 : 민원서류코드가 "1524", "1525", "1526", "1523" 민원인관계가 본인(01)일 경우. 재해근로자정보 -> 민원인정보 
*******************************************************************************/
scwin.fn_FromJaehaejaToMinwonin = function(strColumnID, ColumnValue){

	var v_ColumnID = com.substr(strColumnID, 8);
	var v_NewColumnID = "MINWONIN"+v_ColumnID;
	if (cob_MinwoninInfo_minwoninGwangyeCd.getValue() == "01") {
		dma_JeopsuInfo.set(v_NewColumnID, ColumnValue);
	}
}

