/*******************************************************************************
 * FUNCTION 명 : scwin.fn_MinwoninSet
 * FUNCTION 기능설명 : 민원인 정보 세팅
*******************************************************************************/
scwin.fn_MinwoninSet = function(v_Flag) 
{
    var v_strM       = "MINWONIN_";
    var v_strJ       = "JAEHAEJA_";
    var v_Obj        = dma_JeopsuInfo;

    var v_RtnArr     = Array();
	v_RtnArr[0]="NM";
	v_RtnArr[1]="EMAIL1";
	v_RtnArr[2]="EMAIL2";
	v_RtnArr[3]="EMAIL";
	v_RtnArr[4]="RGNO";
	v_RtnArr[5]="DDD";
	v_RtnArr[6]="TEL1";
	v_RtnArr[7]="TEL2";
	v_RtnArr[8]="HP_DDD";
	v_RtnArr[9]="HP_TEL1";
	v_RtnArr[10]="HP_TEL2";
	v_RtnArr[11]="POST";
	v_RtnArr[12]="POST_SER";
	v_RtnArr[13]="GIBON_ADDR";
	v_RtnArr[14]="SANGSE_ADDR";

	var v_SetVal;
	for(var inx = 0; inx < v_RtnArr.length; inx++) 
	{
		// v_SetVal = decode(v_Flag, true, v_Obj.GetColumn(0, v_strJ + v_RtnArr[inx]), "");
		if (v_Flag == true) {
			v_SetVal = v_Obj.get(v_strJ + v_RtnArr[inx]);
		} else {
			v_SetVal = "";
		}

		v_Obj.set(v_strM + v_RtnArr[inx], v_SetVal);
	}
}	

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_JaehaejaSet
 * FUNCTION 기능설명 : 재해자 정보 세팅
*******************************************************************************/
scwin.fn_JaehaejaSet = function(col_obj) 
{
    if (edt_JaehaejaInfo_jaehaejaNm.getDisabled() == false && dma_JeopsuInfo.get("MINWONIN_GWANGYE_CD") == "01")
    {
	    var v_strM 		 = "MINWONIN_";
	    var v_strJ 		 = "JAEHAEJA_";
	    var v_Obj		 = dma_JeopsuInfo;
	    var v_SetVal;

	    v_SetVal = v_Obj.get(v_strM + col_obj);

		// 생년월일인 경우 복사하지 않고 return
		if (col_obj == "BIRTHDAY") {
			if (!com.isDate(v_SetVal)) {
				return;
			}
		}

		v_Obj.set(v_strJ + col_obj, v_SetVal);


		if (col_obj == "RGNO")
		{
		    dma_JeopsuInfo.set("WONBU_NO", "");
		    scwin.fn_JaehaejaInfoJohoe("keyDown");
		}    
	}
}	

