/*******************************************************************************
 * FUNCTION 명 : scwin.fnc_MinwonSeosikExCheori
 * FUNCTION 기능설명 : 민원서식 처리
*******************************************************************************/
scwin.fnc_MinwonSeosikExCheori = function(obj) {

    // ---------재해자 정보 --------------------------------------
    edt_JaehaejaInfo_jaehaejaNm.setDisabled(false); 
	mae_JaehaejaInfo_jaehaejaRgno.setDisabled(false); 
	btn_JaehaejaInfo_SelectJaehaejaPup.setDisabled(false); 
	chk_Foreigner_Mibalgeup_Yn.setDisabled(false); 
	cal_JaehaejaInfo_jaehaeDt.setDisabled(false); 
	mae_JaehaejaInfo_addr.setDisabled(false); 
	btn_JaehaejaInfo_SelectJaehaejaPostPup.setDisabled(false); 
	// edt_JaehaejaInfo_addr2.setDisabled(false); 
	edt_JaehaejaInfo_addr3.setDisabled(false); 
	edt_JaehaejaInfo_telNo.setDisabled(false); 
	edt_JaehaejaInfo_telNo2.setDisabled(false); 	    
	edt_JaehaejaInfo_telNo4.setDisabled(false); 
	edt_JaehaejaInfo_hpNo.setDisabled(false); 
	edt_JaehaejaInfo_hpNo2.setDisabled(false); 
	edt_JaehaejaInfo_hpNo4.setDisabled(false); 
	edt_JaehaejaInfo_jaehaejaEmail.setDisabled(false); 
	edt_JaehaejaInfo_jaehaejaEmailDomain.setDisabled(false); 
	edt_JaehaejaInfo_jaehaejaEmailCombo.setDisabled(false); 

	// ---------사업장 정보 --------------------------------------
	mae_JaehaejaInfo_hospitalNo.setDisabled(false); 
	btn_JaehaejaInfo_SelectHospitalNoPup.setDisabled(false); 
	mae_JaehaejaInfo_gwanriNo.setDisabled(false); 
	btn_JaehaejaInfo_SelectGwanriNoPup.setDisabled(false); 

	// 2010-08-20  수정 시작 						
	// 민원서식별 예외 처리 
	if ((parseInt(obj) >= 2000 && parseInt(obj) <= 2499) || 
	    obj == "1017" || obj == "1019" || obj == "1020" || obj == "1058" || obj == "1083" || obj == "1081" || //산재전문의사 운영신청서(2018.09.06 추가) 
	    obj == "1059" || obj == "1060" || obj == "1018" || obj == "1016" || obj == "1014" ) {
	    // ---- 재해자 ----------------------------------------
	    edt_JaehaejaInfo_jaehaejaNm.setDisabled(true); 
	    mae_JaehaejaInfo_jaehaejaRgno.setDisabled(true); 
	    btn_JaehaejaInfo_SelectJaehaejaPup.setDisabled(true); 
	    chk_Foreigner_Mibalgeup_Yn.setDisabled(true); 
	    cal_JaehaejaInfo_jaehaeDt.setDisabled(true); 
	    mae_JaehaejaInfo_addr.setDisabled(true); 
	    btn_JaehaejaInfo_SelectJaehaejaPostPup.setDisabled(true); 
	    edt_JaehaejaInfo_addr2.setDisabled(true); 
	    edt_JaehaejaInfo_addr3.setDisabled(true); 
	    edt_JaehaejaInfo_telNo.setDisabled(true); 
	    edt_JaehaejaInfo_telNo2.setDisabled(true); 
	    edt_JaehaejaInfo_telNo4.setDisabled(true); 
	    edt_JaehaejaInfo_hpNo.setDisabled(true); 
		edt_JaehaejaInfo_hpNo2.setDisabled(true); 
		edt_JaehaejaInfo_hpNo4.setDisabled(true); 
		edt_JaehaejaInfo_jaehaejaEmail.setDisabled(true); 
		edt_JaehaejaInfo_jaehaejaEmailDomain.setDisabled(true); 
		edt_JaehaejaInfo_jaehaejaEmailCombo.setDisabled(true); 

		// ---- 사업장 -----------------------------------------
		if (obj == "1017" || obj == "2000" ) {
		    mae_JaehaejaInfo_hospitalNo.setDisabled(true); 
	        btn_JaehaejaInfo_SelectHospitalNoPup.setDisabled(true); 
	    } else if (obj == "1019" || obj == "1020" || obj == "2011" || obj == "2012" || obj == "2014" || obj == "1083" || obj == "1081" || //산재전문의사 운영신청서(2018.09.06 추가) 
	               obj == "2020" ) {
	        mae_JaehaejaInfo_gwanriNo.setDisabled(true); 
	        btn_JaehaejaInfo_SelectGwanriNoPup.setDisabled(true); 
	    } else if (obj == "1016") {
	        mae_JaehaejaInfo_hospitalNo.setDisabled(true); 
	        btn_JaehaejaInfo_SelectHospitalNoPup.setDisabled(true); 
	        mae_JaehaejaInfo_gwanriNo.setDisabled(true); 
	        btn_JaehaejaInfo_SelectGwanriNoPup.setDisabled(true); 
	    } else if (obj == "2018") {
	        mae_JaehaejaInfo_gwanriNo.setDisabled(true); 
	        btn_JaehaejaInfo_SelectGwanriNoPup.setDisabled(true); 
	    }
	} else if (obj == "1504" || obj == "1524" || obj == "1525") {
	    mae_JaehaejaInfo_hospitalNo.setDisabled(true); 
	    btn_JaehaejaInfo_SelectHospitalNoPup.setDisabled(true); 
	}
	// 2010-08-20 수정 끝 
}

