/*******************************************************************************
 * FUNCTION 명 : scwin.edt_JeopsuInfo_jeopsuIlsi_onviewchange
 * FUNCTION 기능설명 : 접수일시 변경
*******************************************************************************/
scwin.edt_JeopsuInfo_jeopsuIlsi_onviewchange = async function(info)
{   
	var oldValue = info.oldValue;
	var newValue = info.newValue;

    if (com.gfn_IsNull(dma_JeopsuInfo.get("MINWON_DOC_CD"))){
        await com.gfn_Alert("민원서류코드를 먼저 입력하시십오."); 
		edt_JeopsuInfo_jeopsuIlsi.setValue(oldValue);
        edt_JeopsuInfo_minwonDocCd.focus();
        return false; 
    }

    if (com.gfn_IsNull(edt_JeopsuInfo_jeopsuIlsi.getValue())){
        await com.gfn_Alert("접수일시가 없습니다."); 
        return false; 
    }

    if (com.gfn_IsValidDate(com.substr(newValue, 0, 8), "YYYYMMDD") == false) {
		edt_JeopsuInfo_jeopsuIlsi.setValue(oldValue);
        await com.gfn_Alert("부적합한 일자입니다."); 
        return false ; 
    }

	if (com.gfn_IsValidTime(com.substr(newValue , 8), "HHMM") == false) {
		edt_JeopsuInfo_jeopsuIlsi.setValue(oldValue);
	    await com.gfn_Alert("부적합한 일시입니다."); 
	    return false; 
	}

	edt_JeopsuInfo_jeopsuIlsi.setValue(newValue);
	edt_JeopsuInfo_jeopsuIlsi.commit();

    var v_GihanArr ; 

    if (com.gfn_IsNull(dma_JeopsuInfo.get("JEOPSU_NO"))) {

        if (!com.gfn_IsNull(newValue) && com.length(newValue) == 12) {  //as-is 소스 변경 4 -> 12
            v_GihanArr = await scwin.fn_RetrieveMinwonCheoriGihan(); 

	        if (!com.gfn_IsNull(v_GihanArr[0])) {
	             dma_JeopsuInfo.set("CHEORI_GIHAN", v_GihanArr[0]); 
	        }
        } else {
	        dma_JeopsuInfo.set("CHEORI_GIHAN", ""); 
	    }
     }        
}

/*******************************************************************************
 * FUNCTION 명 : scwin.edt_JeopsuInfo_jeopsuIlsi_onviewchange
 * FUNCTION 기능설명 : 접수일시 변경
*******************************************************************************/
scwin.fn_RetrieveMinwonCheoriGihan = async function() {
    var v_GihanArr      = Array(); 
    var v_Jisa_Cd       = com.gfn_SsJisaCd(); 
    var v_Minwon_Doc_Cd = dma_JeopsuInfo.get("MINWON_DOC_CD"); 
    var v_Jeopsu_Ilsi   = dma_JeopsuInfo.get("JEOPSU_ILSI");
    var v_Sj_Yn         = dma_JeopsuInfo.get("");
    var v_Gy_yn         = dma_JeopsuInfo.get("");

	v_GihanArr = await qa.cfn_RetrieveMinwonCheoriGihan(v_Jisa_Cd, v_Minwon_Doc_Cd, '', v_Jeopsu_Ilsi, v_Sj_Yn , v_Gy_yn ) ; 
	return v_GihanArr ; 
}

