/*******************************************************************************
 * FUNCTION 명 : scwin.edt_DamdangjaInfo_GeonseolInfo1_onviewchange
 * FUNCTION 기능설명 : 담당자 정보 변경
*******************************************************************************/
scwin.edt_DamdangjaInfo_GeonseolInfo1_onviewchange = async function(info)
{
	var strText = info.newValue;

     if (!com.gfn_IsNull(dma_JeopsuInfo.get("JEOPSU_NO"))) {
		var v_Flag = "keyDown";
		var v_Param = "v_UserId=" + dma_JeopsuInfo.get("DAMDANGJA_ID");
		var v_UserInfo = Array();

		v_UserInfo = await com.gfn_GetUserInfo(v_Flag, v_Param);

		if (!com.gfn_IsNull(v_UserInfo[0])) {
			dma_JeopsuInfo.set("DAMDANGJA_NM", v_UserInfo[1]);			
			dma_JeopsuInfo.set("DAMDANGJA_ID", v_UserInfo[0]);
            edt_DamdangjaInfoJisa.setValue(v_UserInfo[2]);

			if (dma_JeopsuInfo.get("DAMDANGJA_ID") != dma_JeopsuInfo.get("FIRST_DAMDANGJA_ID")) {
				cob_DamdangjaInfo_damdangjaChangeSayuCd.setDisabled(false);
			} else {
				cob_DamdangjaInfo_damdangjaChangeSayuCd.setDisabled(true);
				cob_DamdangjaInfo_damdangjaChangeSayuCd.setValue("");
			}		

			if (dma_JeopsuInfo.get("DAMDANGJA_ID") == "TOTAL") {
				btn_DamdangjaInfo_DamdangjaJijeong.setDisabled(true);
			}	 
		} 
    } else {
		if (!com.gfn_IsNull(strText))  {
			var v_MinwonDamdang = Array(); 
			if (1 == 1) { 
				scwin.fn_Tmp();
				edt_DamdangjaInfo_GeonseolInfo1.focus(); 

				return; 
			} else {
				// 있다 하더라도 다를 경우 
				if (strText != v_MinwonDamdang[1]) {
					await com.gfn_Alert("입력된 담당자가 업무분장별담당자등록(1.12.1) 화면에 지정된 담당자 정보가 아닙니다. "); 

					dma_JeopsuInfo.set("DAMDANGJA_NM", "");
					dma_JeopsuInfo.set("DAMDANGJA_ID", ""); 

					edt_DamdangjaInfo_GeonseolInfo1.focus() ; 
					return; 
				} else {
					dma_JeopsuInfo.set("DAMDANGJA_NM", v_MinwonDamdang[0]);

					//담당자ID와 최초담당자 ID의 정보가 다를 경우 
					if (com.gfn_IsNull(dma_JeopsuInfo.get("FIRST_DAMDANGJA_ID"))) {
						dma_JeopsuInfo.set("FIRST_DAMDANGJA_NM", dma_JeopsuInfo.get("DAMDANGJA_NM"));  
						dma_JeopsuInfo.set("FIRST_DAMDANGJA_ID", dma_JeopsuInfo.get("DAMDANGJA_ID"));         
					}

					if (dma_JeopsuInfo.get("DAMDANGJA_ID") != dma_JeopsuInfo.get("FIRST_DAMDANGJA_ID"))  {
						cob_DamdangjaInfo_damdangjaChangeSayuCd.setDisabled(false);
					} else {
						cob_DamdangjaInfo_damdangjaChangeSayuCd.setDisabled(true);
						cob_DamdangjaInfo_damdangjaChangeSayuCd.setValue("");
					}		

					if (dma_JeopsuInfo.get("DAMDANGJA_ID") == "TOTAL") {
						btn_DamdangjaInfo_DamdangjaJijeong.setDisabled(true);
					}	
				}
			}
		}
    }
}

