*******************************************************************************/
scwin.edt_JaehaejaInfo_telNo_onviewchange = async function(info)
{
	var varOldValue = info.oldValue;
	var varNewValue = info.newValue;

	if (com.gfn_ChkDddNo("DDD", varNewValue) == false){
	    await com.gfn_Alert("전화지역번호가 부적합합니다."); 
		edt_JaehaejaInfo_telNo.setValue(varOldValue);
	    return false ; 
	}

	scwin.fn_JaehaejaToMinwonin("DDD");
}

