/*******************************************************************************
 * FUNCTION 명 : scwin.fn_JaehaejaToMinwonin
 * FUNCTION 기능설명 : 재해자 정보 민원인으로 변경
*******************************************************************************/
scwin.fn_JaehaejaToMinwonin = function(col_obj) {
    if (dma_JeopsuInfo.get("MINWONIN_GWANGYE_CD") == "01") {
	    var v_strM 		 = "MINWONIN_";
	    var v_strJ 		 = "JAEHAEJA_";
	    var v_Obj		 = dma_JeopsuInfo;
	    var v_SetVal;

	    v_SetVal = v_Obj.get(v_strJ + col_obj);
		v_Obj.set(v_strM + col_obj, v_SetVal);
	}
}	

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_DamdangjaInfo
 * FUNCTION 기능설명 : 담당자 정보 조회
*******************************************************************************/
scwin.fn_DamdangjaInfo = function() {

    dma_DamdangjaJeopsuInfo.setEmptyValue(); 

	if (com.gfn_IsNull(dma_JeopsuInfo.get("CHEORI_JISA_CD"))) {
	    dma_JeopsuInfo.set("CHEORI_JISA_CD", com.gfn_SsJisaCd());
	}

	//dma_DamdangjaJeopsuInfo.CopyRow(0, "dma_JeopsuInfo", 0);
	dma_DamdangjaJeopsuInfo.setJSON(dma_JeopsuInfo.getJSON());	
	dlt_DamdangjaInfo.removeAll();
	dlt_DamdangjaInfo.setRowJSON(0, dma_DamdangjaJeopsuInfo.getJSON(), false);

	/*
	var srvId		 = "RetrieveBosangDamdangjaCmd";
	var strURL		 = "kcw.q.qa.cmd.RetrieveBosangDamdangjaCmd.do";
	var strinDsList	 = "dma_JeopsuInfo=dma_DamdangjaJeopsuInfo";
	var stroutDsList = "dma_DamdangjaInfo=dma_DamdangjaInfo";
	var strArgument	 = "";
	var strCallback  = "scwin.fn_CallBack";

	com.gfn_CallService(srvId, strURL, strinDsList, stroutDsList, strArgument, strCallback, true, true, true);	
	*/

	// RetrieveBosangDamdangjaCmd
	com.executeSubmission(sbm_CM0101100M_E006);

    var v_MinwonDamdang = Array(); 

    if (!com.gfn_IsNull(dma_DamdangjaInfo.get("USER_NM"))) {
        v_MinwonDamdang[0] = dma_DamdangjaInfo.get("USER_NM");
		v_MinwonDamdang[1] = dma_DamdangjaInfo.get("USER_ID");
	}else{
	    v_MinwonDamdang[0] = ""; 
	    v_MinwonDamdang[1] = ""; 
	}

	return v_MinwonDamdang; 	
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_Tmp
 * FUNCTION 기능설명 : 사용자정보 조회 추후 삭제 
*******************************************************************************/
scwin.fn_Tmp = async function() {
	var v_Flag1     = "keyDown";
	var v_Param1    = "v_UserId=" + dma_JeopsuInfo.get("DAMDANGJA_ID");
	var v_UserInfo1 = Array();

	v_UserInfo1 = await com.gfn_GetUserInfo(v_Flag1, v_Param1);

	if (!com.gfn_IsNull(v_UserInfo1[0])) {
	    dma_JeopsuInfo.set("DAMDANGJA_NM", v_UserInfo1[1]);	
	    dma_JeopsuInfo.set("DAMDANGJA_ID", v_UserInfo1[0]);
	} 

	// 담당자ID와 최초담당자 ID의 정보가 다를 경우 
	if (com.gfn_IsNull(dma_JeopsuInfo.get("FIRST_DAMDANGJA_ID")) && !com.gfn_IsNull(dma_JeopsuInfo.get("DAMDANGJA_NM"))) {
		dma_JeopsuInfo.set("FIRST_DAMDANGJA_NM", dma_JeopsuInfo.get("DAMDANGJA_NM"));  
		dma_JeopsuInfo.set("FIRST_DAMDANGJA_ID", dma_JeopsuInfo.get("DAMDANGJA_ID"));         
	}

	if ((dma_JeopsuInfo.get("DAMDANGJA_ID") != dma_JeopsuInfo.get("FIRST_DAMDANGJA_ID")) && 
	    !com.gfn_IsNull(dma_JeopsuInfo.get("FIRST_DAMDANGJA_ID")) && 
	    !com.gfn_IsNull(dma_JeopsuInfo.get("DAMDANGJA_NM"))) {
		cob_DamdangjaInfo_damdangjaChangeSayuCd.setDisabled(false);
	} else {
		cob_DamdangjaInfo_damdangjaChangeSayuCd.setDisabled(true);
		cob_DamdangjaInfo_damdangjaChangeSayuCd.setValue("");
	}		

	if (dma_JeopsuInfo.get("DAMDANGJA_ID") == "TOTAL") {
		btn_DamdangjaInfo_DamdangjaJijeong.setDisabled(true);
	}
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_WonbuCheckYn
 * FUNCTION 기능설명 : 원부체크
// 최초요양 급여신청서 TRUE  
// 재해자주민번호 또는 재해일자 중 하나라도 미입력시 TURE  
// 원부번호가 있을 경우 true 
// 재해자주민번호 및 재해일자로 조회하여 원부번호가 없을 경우 TRUE , 원부번호가 있을 경우 FALSE 
*******************************************************************************/
scwin.fn_WonbuCheckYn = function(v_MinwonDocCd, v_JaehaejaRgno, v_JaehaeDt, v_WonbuNo){

    if (v_MinwonDocCd == "1001") {
        return true ; 
    } else if (com.gfn_IsNull(v_JaehaejaRgno) || com.gfn_IsNull(v_JaehaeDt)) {
        return true ; 
    } else {
        if (com.gfn_IsNull(v_WonbuNo)) {
			/*
        	Create("dataSet", "CDS_JOHEOJOGEON");
			Create("dataSet", "CDS_JAEHAEJAINFO");
			CDS_JOHEOJOGEON.ClearData();
			CDS_JAEHAEJAINFO.ClearData();

			CDS_JOHEOJOGEON.AddColumn("JAEHAEJA_RGNO", "String", 256);
			CDS_JOHEOJOGEON.AddColumn("JAEHAE_DT", "String", 256);
			CDS_JOHEOJOGEON.AddRow();
			CDS_JOHEOJOGEON.SetColumn(0, "JAEHAEJA_RGNO", v_JaehaejaRgno);
			CDS_JOHEOJOGEON.SetColumn(0, "JAEHAE_DT", v_JaehaeDt);
			*/
			/*
			var srvId		 = "RetrieveDongilDtJungbokJaehaejaNaeyeokCmd";
			var strURL		 = "kcw.a.aa.cmd.RetrieveDongilDtJungbokJaehaejaNaeyeokCmd.do";
			var strinDsList	 = "ds_JohoeJogeon=CDS_JOHEOJOGEON";
			var stroutDsList = "CDS_JAEHAEJAINFO=ds_JaehaeInfo";
			var strArgument	 = "";
			var strCallback  = "";
			com.gfn_CallService(srvId, strURL, strinDsList, stroutDsList, strArgument, strCallback, true, true, true);
			*/
			dma_JaHaejajohoeJogeon.setEmptyValue();
			dma_JaHaejajohoeJogeon.set("JAEHAEJA_RGNO", v_JaehaejaRgno);
			dma_JaHaejajohoeJogeon.set("JAEHAE_DT"    , v_JaehaeDt);

			// RetrieveDongilDtJungbokJaehaejaNaeyeokCmd
			com.executeSubmission(sbm_CM0101100M_E011);

			if (dlt_JaHaejaInfo.getRowCount() < 1) {
				return true ; 
			} else {
			    return false ; 
			}
		}else{
		    return true ; 
		}
    }
}

/*******************************************************************************
 * FUNCTION 명 : scwin.mae_SaeopjangInfo_saeopjangGaesiNo_onviewchange
 * FUNCTION 기능설명 : 사업장 개시번호 변경
*******************************************************************************/
scwin.mae_SaeopjangInfo_saeopjangGaesiNo_onviewchange = async function(info)
{   
	debugger;
	// 특수형태근로자(20210615_AM_01) 인 경우 동일위험사업장관리번호 set (2021.06.28)
	var v_GwanriNo = dma_JeopsuInfo.get("GWANRI_NO");

	// 특고이면서 사업개시사업장이 없는 경우에만 동일위험관리번호 SET (2021.07.16)
	if (!com.gfn_IsNull(dma_JeopsuInfo.get("DONGIL_RISK_GWANRI_NO")) && dma_JeopsuInfo.get("TS_GS_SAEOP_YN") != "Y") {
		v_GwanriNo = dma_JeopsuInfo.get("DONGIL_RISK_GWANRI_NO");
	}

	var v_Param = "v_SaeopgaesiNo=" + dma_JeopsuInfo.get("SAEOPGAESI_NO") + " v_IlgwalGwanriNo=" + v_GwanriNo;

	var vRtnInfo = Array();
	var v_Msg    = Array(); 	
	dma_JeopsuInfo.set("GS_WONBU_NO", "");

	if (com.gfn_IsNull(dma_JeopsuInfo.get("SAEOPGAESI_NO"))) {
	    return; 
	}

	// 개시번호가 입력되었을 경우 
	if (!com.gfn_IsNull(dma_JeopsuInfo.get("SAEOPGAESI_NO"))){
		// 개시사업장 조회 동적데이터 셋 생성 
		/*
		Create("dataSet", "CDS_GaesiSaeopjangJogeon"); 
		Create("dataSet", "CDS_GaesiSaeopjangList"  ); 

		CDS_GaesiSaeopjangJogeon.ClearData(); 
		CDS_GaesiSaeopjangList.clearData(); 

		// 조회조건 컬럼 생성 
		CDS_GaesiSaeopjangJogeon.AddColumn("GWANRI_JISA_CD"    , "String", 256);
		CDS_GaesiSaeopjangJogeon.AddColumn("GWANRI_JISA_NM"    , "String", 256);
		CDS_GaesiSaeopjangJogeon.AddColumn("JOHOE_JOGEON"      , "String", 256);
		CDS_GaesiSaeopjangJogeon.AddColumn("JOHOE_JOGEON_VALUE", "String", 256);
		CDS_GaesiSaeopjangJogeon.AddRow(); 
		CDS_GaesiSaeopjangJogeon.SetColumn(0, "JOHOE_JOGEON"        , "1" ); 
		CDS_GaesiSaeopjangJogeon.SetColumn(0, "JOHOE_JOGEON_VALUE"  , dma_JeopsuInfo.get("SAEOPGAESI_NO")   ); 
		*/
		/*
		var v_srvId		    = "RetrieveGaesiSaeopjangCmd";
		var v_strURL	    = "kcw.k.kd.cmd.RetrieveGaesiSaeopjangCmd.do";
		var v_strinDsList	= "ds_GaesiSaeopjangJogeon=CDS_GaesiSaeopjangJogeon";
		var v_stroutDsList  = "CDS_GaesiSaeopjangList=ds_GaesiSaeopjangList";
		var v_strArgument	= "";
		var v_strCallback   = "";

		com.gfn_CallService(v_srvId, v_strURL, v_strinDsList, v_stroutDsList, v_strArgument, v_strCallback, true, true, true);	
		*/
		dma_GaesiSaeopjangJogeon.setEmptyValue();
		dma_GaesiSaeopjangJogeon.set("JOHOE_JOGEON"       , "1" ); 
		dma_GaesiSaeopjangJogeon.set("JOHOE_JOGEON_VALUE" , dma_JeopsuInfo.get("SAEOPGAESI_NO")); 

		// RetrieveGaesiSaeopjangCmd
		com.executeSubmission(sbm_CM0101100M_E009);	

		if (dlt_GaesiSaeopjangInfo.getRowCount() > 0) {
			if (v_GwanriNo != dlt_GaesiSaeopjangInfo.getCellData(0, "ILGWAL_GWANRI_NO")) {  //20210615_AM_01 변수 지정 기존  dma_JeopsuInfo.get("GWANRI_NO") -> v_GwanriNo (2021.06.28)  
				v_Msg[0] = "관리번호에 해당하는 사업개시번호"; 
				await com.gfn_MsgAlert("MZZA087", v_Msg);
				mae_SaeopjangInfo_saeopjangGaesiNo.focus();
				dma_JeopsuInfo.set("GS_WONBU_NO", ""); 

				return ; 
			} else {				
				dma_JeopsuInfo.set("SAEOPGAESI_NO"     , dlt_GaesiSaeopjangInfo.getCellData(0, "SAEOP_GAESI_NO"));
				dma_JeopsuInfo.set("GS_WONBU_NO"       , dlt_GaesiSaeopjangInfo.getCellData(0, "GS_WONBU_NO"));
				// dma_JeopsuInfo.set("GONGSA_NM"      , dlt_GaesiSaeopjangInfo.getCellData(0, "SAEOPJANG_NM"));   
				return ; 
			}    
		}
	}

	// 개시번호가 미입력되었거나 , 위에서 조회한 개시사업장이 1건이 아닐 경우 
	var option = {id : "upyeonmulSudongDeungrok", type : "wframePopup", popupName : "개시사업장정보조회" , modal : true, width : 1000, height : 600};	
	var vRtnInfo = await com.openPopup("/ui/sia/biz/kd/kd00/0000/KD00001150P.xml", option, com.paramStringToJSON(v_Param, [' ','='], false));

	if (!com.gfn_IsNull(vRtnInfo[0])) {	
		if (v_GwanriNo != vRtnInfo[0]){  //20210615_AM_01 변수 지정 기존 dma_JeopsuInfo.get("GWANRI_NO") -> v_GwanriNo (2021.06.28)  
			var v_Msg = Array();
			v_Msg[0] = "관리번호에 해당하는 사업개시번호"; 
			await com.gfn_MsgAlert("MZZA087", v_Msg);
			dma_JeopsuInfo.set("GS_WONBU_NO", ""); 

			mae_SaeopjangInfo_saeopjangGaesiNo.focus();
			return ; 
		} else {
			dma_JeopsuInfo.set("SAEOPGAESI_NO", vRtnInfo[2]);
			dma_JeopsuInfo.set("GS_WONBU_NO"  , vRtnInfo[3]);
			//dma_JeopsuInfo.set("GONGSA_NM"      ,  vRtnInfo[4]);                

		}    
	} else {
		mae_SaeopjangInfo_saeopjangGaesiNo.focus();
	}
}

