/*******************************************************************************
 * FUNCTION 명 : scwin.btn_SaeopjangInfo_RetrieveSaeopgaesiNoPup_onclick
 * FUNCTION 기능설명 : 사업장 개시번호 팝업
*******************************************************************************/
scwin.btn_SaeopjangInfo_RetrieveSaeopgaesiNoPup_onclick = async function(e)
{
	// 특수형태근로자(20210615_AM_01) 인 경우 동일위험사업장관리번호 set (2021.06.28)
	var v_GwanriNo = dma_JeopsuInfo.get("GWANRI_NO");

	// 특고이면서 사업개시사업장이 없는 경우에만 동일위험관리번호 SET (2021.07.19)
	if (!com.gfn_IsNull(dma_JeopsuInfo.get("DONGIL_RISK_GWANRI_NO")) && dma_JeopsuInfo.get("TS_GS_SAEOP_YN") != "Y") {
		v_GwanriNo = dma_JeopsuInfo.get("DONGIL_RISK_GWANRI_NO");
	}

	var v_Flag = "click";
	var v_Param = "v_SaeopgaesiNo=" + dma_JeopsuInfo.get("SAEOPGAESI_NO") + 
				  " v_IlgwalGwanriNo=" + v_GwanriNo; // 20210615_AM_01 기존 (dma_JeopsuInfo.get("GWANRI_NO")) 변수 지정 (2021.06.28)  

	// 개시번호가 미입력되었거나 , 위에서 조회한 개시사업장이 1건이 아닐 경우 
	var option = {id : "getGaesiInfoPop", type : "wframePopup", popupName : "개시사업장정보조회" , modal : true, width : 1000, height : 520};
	var vRtnInfo = await com.openPopup("/ui/sia/biz/kd/kd00/0000/KD00001150P.xml", option, com.paramStringToJSON(v_Param, [' ','='], false));

	if (!com.gfn_IsNull(vRtnInfo[0])) {	
	    if (v_GwanriNo != vRtnInfo[0]) {   //20210615_AM_01 변수 지정 기존 dma_JeopsuInfo.get("GWANRI_NO") -> v_GwanriNo (2021.06.28)  
			var v_Msg = Array();
	        v_Msg[0] = "관리번호에 해당하는 사업개시번호"; 
	        await com.gfn_MsgAlert("MZZA087", v_Msg);
	        dma_JeopsuInfo.set("SAEOPGAESI_NO", "");

	        mae_SaeopjangInfo_saeopjangGaesiNo.focus();
            return ; 
        } else {
		    dma_JeopsuInfo.set("SAEOPGAESI_NO", vRtnInfo[2]);
		    dma_JeopsuInfo.set("GS_WONBU_NO"  , vRtnInfo[3]);
		}    
	} else {
	    mae_SaeopjangInfo_saeopjangGaesiNo.focus();
	}
}

