/*******************************************************************************
 * FUNCTION 명 : scwin.btn_MOEL_Tongbo_onclick
 * FUNCTION 기능설명 : 노동부 전자 통보 버튼 클릭
*******************************************************************************/
scwin.btn_MOEL_Tongbo_onclick = async function(e)
{
	var v_GJJeopsuNo    = dma_JeopsuInfo.get("JEOPSU_NO");
	var v_GJSeunginFG   = "";
	var v_GJMinwonDocCD = dma_JeopsuInfo.get("MINWON_DOC_CD");
	var v_GJMinwonFG    = dma_JeopsuInfo.get("MINWON_FG");

	//공통결재정보 조회 
	var v_GyeoljaeStatus = $p.parent().gyeoljaeBar.gfn_GtGyeoljaeInfo(v_GJJeopsuNo, v_GJSeunginFG, v_GJMinwonDocCD, v_GJMinwonFG);

	if ((v_GyeoljaeStatus == "1" || v_GyeoljaeStatus == "0") && v_GJMinwonDocCD == "1534") {

		dma_CdsJeopsuInfo.setEmptyValue();
		dma_CdsJeopsuInfo.set("JEOPSU_NO", v_GJJeopsuNo);

		// CreateBosangMinwonMOELJeonsongCmd
		com.executeSubmission(sbm_CM0101100M_E007);
	} else if (v_GJMinwonDocCD != "1534") {
		await com.gfn_Alert("노동부통보대상 민원 서류가 아닙니다");
	} else if (v_GyeoljaeStatus != "0" && v_GyeoljaeStatus != "1") {
		await com.gfn_Alert("노동부통보 가능한 결재상태가 아닙니다");
	}
}

