/*******************************************************************************
 * FUNCTION 명 : scwin.fn_DonguiCheoriYn
 * FUNCTION 기능설명 : 동의처리 여부 조회
*******************************************************************************/
scwin.fn_DonguiCheoriYn = function(v_No, v_Fg){

    if (com.gfn_IsNull(v_No) || com.gfn_IsNull(v_Fg)) {
        return "N" ;  
    } else {

		dma_DongUiseoJohoeJogeon.setEmptyValue();
		dma_DongUiseoJohoeJogeon.set("DONGUIJA_NO", v_No);
		dma_DongUiseoJohoeJogeon.set("DONGUIJA_FG", v_Fg);

		// 개인정보이용문항목록조회
		// RetrieveGaeinInfoIyongMunhangMokrokCmd
		com.executeSubmission(sbm_CM0101100M_E007);

		if (com.gfn_IsNull(dma_DongUiseoDetail.get("DONGUIJA_NO"))) {
			return "Y"; 
		} else {
			return "N"; 
		}
	}

}

