/*******************************************************************************
 * FUNCTION 명 : scwin.fn_checkRgnoOrBirthday
 * FUNCTION 기능설명 : 생년월일 체크
*******************************************************************************/
scwin.fn_checkRgnoOrBirthday = function(av_flag, av_value)
{
	 if (av_value == "1010" || av_value == "3812") {
		if (av_flag == "LOAD" && (!com.gfn_IsNull(dma_JeopsuInfo.get("MINWONIN_RGNO")) || !com.gfn_IsNull(dma_JeopsuInfo.get("JAEHAEJA_RGNO")))) {
			scwin.fn_resetRgnoOrBirthday("RGNO");
		} else { 	
			scwin.fn_resetRgnoOrBirthday("BIRTHDAY"); 
		}
	 } else {
		scwin.fn_resetRgnoOrBirthday("RGNO");
	 }
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_resetRgnoOrBirthday
 * FUNCTION 기능설명 : 생년월일 체크
*******************************************************************************/
scwin.fn_resetRgnoOrBirthday = function(av_flag)
{
	 if ( av_flag == "BIRTHDAY") {
		st_MinwoninInfo_tb113_h_minwoninRgno.setValue("생년월일");
		st_JaehaejaInfo_tb113_h_jaehaejaRgno.setValue("근로자생년월일");
		cal_JaehaejaInfo_birthday.show();
		cal_MinwoninInfo_birthday.show();
		cob_JaehaejaGenderFg.show();
		cob_MinwoninGenderFg.show();

		grp_Jaehaeja.setStyle("display", "");
		grp_MinwoninInfo.setStyle("display", "");

		mae_JaehaejaInfo_jaehaejaRgno.hide();
		btn_JaehaejaInfo_SelectJaehaejaPup.hide();
		mae_MinwoninInfo_minwoninRgno.hide();
		btn_MinwoninInfo_RetrieveMinwoninNmPup.hide();
	 } else {
		st_MinwoninInfo_tb113_h_minwoninRgno.setValue("주민등록번호");
		st_JaehaejaInfo_tb113_h_jaehaejaRgno.setValue("근로자주민등록번호");
		cal_JaehaejaInfo_birthday.hide();
		cal_MinwoninInfo_birthday.hide();
		cob_JaehaejaGenderFg.hide();
		cob_MinwoninGenderFg.hide();

		grp_Jaehaeja.setStyle("display", "none");
		grp_MinwoninInfo.setStyle("display", "none");

		mae_JaehaejaInfo_jaehaejaRgno.show();
		btn_JaehaejaInfo_SelectJaehaejaPup.show();
		mae_MinwoninInfo_minwoninRgno.show();
		btn_MinwoninInfo_RetrieveMinwoninNmPup.show();
	 }
}

