*******************************************************************************/
scwin.fn_DaeriinYn_OnChanged = function()
{
	if (dma_JeopsuInfo.get("DAERIIN_SUIM_YN") == "Y") {
		cob_DaeriinInfo_daeriinFg.setDisabled(false);
		edt_DaeriinInfo_daeriinNm.setDisabled(false);
		edt_DaeriinInfo_daeriinGaeeopNo.setDisabled(false);
		edt_DaeriinInfo_jikchaekNm.setDisabled(true);
		edt_DaeriinInfo_hpDDD.setDisabled(false);
		edt_DaeriinInfo_hpTel1.setDisabled(false);
		edt_DaeriinInfo_hpTel2.setDisabled(false);
		/*
		edt_DaeriinInfo_daeriinGaeeopNo.UserData = "";	
		st_DaeriinInfo_tb117_h_daeriinGaeeopNo.color = "user0";	
		edt_DaeriinInfo_jikchaekNm.UserData = "";	
		st_DaeriinInfo_jikchaekNm.color = "user0";
		*/
		edt_DaeriinInfo_daeriinGaeeopNo.setMandatory(false);
		st_DaeriinInfo_tb117_h_daeriinGaeeopNo.setStyle("class", "");
		edt_DaeriinInfo_jikchaekNm.setMandatory(false);
		st_DaeriinInfo_jikchaekNm.setStyle("class", "");

		if (dma_JeopsuInfo.get("MINWON_DOC_CD") == "1001") {
			/*			
			cob_DaeriinInfo_daeriinFg.UserData = "optional=required";		
			edt_DaeriinInfo_daeriinNm.UserData = "optional=required";			
			edt_DaeriinInfo_hpDDD.UserData = "optional=required";		
