			st_DaeriinInfo_tb115_h_daeriinNm.color = "user31";			
			st_DaeriinInfo_tb113_h_daeriinFg.color = "user31";
			st_DaeriinInfo_tb115_h_daeriinTel.color = "user31";
			*/
			st_DaeriinInfo_tb115_h_daeriinNm.setStyle("class" , "req");
			st_DaeriinInfo_tb113_h_daeriinFg.setStyle("class" , "req");
			st_DaeriinInfo_tb115_h_daeriinTel.setStyle("class", "req");

			if (dma_JeopsuInfo.get("DAERIIN_FG") == "1" || dma_JeopsuInfo.get("DAERIIN_FG") == "2") { //대리인구분이 변호사 또는 노무사인 경우
				// edt_DaeriinInfo_daeriinGaeeopNo.UserData = "optional=required";	
				// st_DaeriinInfo_tb117_h_daeriinGaeeopNo.color = "user31";
				edt_DaeriinInfo_daeriinGaeeopNo.setMandatory(true);
				st_DaeriinInfo_tb117_h_daeriinGaeeopNo.setStyle("class", "req");
			} else if (dma_JeopsuInfo.get("DAERIIN_FG") == "7") { //대리인구분이 외국공관노무담당인 경우
				edt_DaeriinInfo_jikchaekNm.setDisabled(false);
				// edt_DaeriinInfo_jikchaekNm.UserData = "optional=required";	
				// st_DaeriinInfo_jikchaekNm.color = "user31";
				edt_DaeriinInfo_jikchaekNm.setMandatory(true);
				st_DaeriinInfo_jikchaekNm.setStyle("class", "req");
			} 
		} else {
			/*
			cob_DaeriinInfo_daeriinFg.UserData = "";		
			edt_DaeriinInfo_daeriinNm.UserData = "";			
			edt_DaeriinInfo_hpDDD.UserData = "";		
			edt_DaeriinInfo_hpTel1.UserData = "";		
			edt_DaeriinInfo_hpTel2.UserData = "";		
