			st_DaeriinInfo_tb113_h_daeriinFg.color = "user0";
			st_DaeriinInfo_tb115_h_daeriinTel.color = "user0";
			*/
			st_DaeriinInfo_tb115_h_daeriinNm.setStyle("class", "");
			st_DaeriinInfo_tb113_h_daeriinFg.setStyle("class", "");
			st_DaeriinInfo_tb115_h_daeriinTel.setStyle("class", "");

			if (dma_JeopsuInfo.get("DAERIIN_FG") == "7") {
				edt_DaeriinInfo_jikchaekNm.setDisabled(false);
			}
		}

	} else if (dma_JeopsuInfo.get("DAERIIN_SUIM_YN") == "N") {
		cob_DaeriinInfo_daeriinFg.setDisabled(true);
		edt_DaeriinInfo_daeriinNm.setDisabled(true);
		edt_DaeriinInfo_daeriinGaeeopNo.setDisabled(true);
		edt_DaeriinInfo_jikchaekNm.setDisabled(true);
