*******************************************************************************/ 
scwin.cal_JaehaejaInfo_jaehaeDt_ondateselect = function(dateStr,dateObj) {
	if (mae_JaehaejaInfo_addr.getDisabled()) {
		edt_JaehaejaInfo_telNo.focus();
	} else {
		mae_JaehaejaInfo_addr.focus();
	}
};

/*******************************************************************************
 * FUNCTION 명 : scwin.cal_JaehaejaInfo_jaehaeDt_onkeydown
 * FUNCTION 기능설명 : 재해일자 엔터
*******************************************************************************/ 
scwin.cal_JaehaejaInfo_jaehaeDt_onkeydown = function(e) {
	if (e.keyCode == 13) {
		if (mae_JaehaejaInfo_addr.getDisabled()) {
			com.dateValidFormatNextFocus2(cal_JaehaejaInfo_jaehaeDt.getValue(), "cal_JaehaejaInfo_jaehaeDt", "edt_JaehaejaInfo_telNo");
		} else {
			com.dateValidFormatNextFocus2(cal_JaehaejaInfo_jaehaeDt.getValue(), "cal_JaehaejaInfo_jaehaeDt", "mae_JaehaejaInfo_addr");
		}
	}	
};

